-- Hand-written spacetech lessons, days 6-30 (100 stacks: one per day and learner goal).
-- Tagged handwritten-v1, so Days 1-30 pick them over older generated stacks (mobile/lib/handwritten.ts).
-- Safe to run more than once: stacks upsert on id, and each stack's slides are replaced.
-- Too large for Lovable to paste: the load-handwritten-lessons edge functions write these same rows
-- (scripts/lessons/export_loader.py).
BEGIN;
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tags = EXCLUDED.tags, stack_type = EXCLUDED.stack_type,
  authored_lesson = EXCLUDED.authored_lesson, duration_minutes = EXCLUDED.duration_minutes,
  published_at = COALESCE(stacks.published_at, EXCLUDED.published_at);

DELETE FROM slides WHERE stack_id IN ('daa7d015-941e-547b-bf11-7f5e705bfed0'::uuid, '8d80b9ac-0eea-5d27-b4e8-e06a3a7e73e1'::uuid, '5c2043b4-1298-5139-8669-8721da957115'::uuid, 'a4469efe-4ea5-57ef-afb6-081d2bfa707a'::uuid, '17478646-1bdd-59ea-b928-d029ba73276d'::uuid, 'd6677782-d752-5078-8d13-bc87b7251eec'::uuid, 'd5a57b55-c6d6-57cf-aa1d-d32a986e764e'::uuid, '28a8fdd2-08d7-517b-9137-671ddbdc40c3'::uuid, 'c651c3e2-ada6-5bab-88e9-540e8ed31976'::uuid, 'a0212085-abf4-5e4b-9a31-50ba19dacf00'::uuid, '440d1c24-e778-53d9-8c1d-938797b19054'::uuid, 'd65b560f-469e-5695-abdd-0496e60328ac'::uuid, 'b6e8230d-b715-5ee0-9dde-fb5a52be65e5'::uuid, '60a410fc-bf99-5eda-8950-343e9766b61a'::uuid, '31f6eaf6-7000-5f4c-8f3b-24ddecb1c3de'::uuid, '2caab2b2-5efa-5beb-97ef-7bd1878265fe'::uuid, '03cb49a3-a3ae-52ef-824a-a5cbbdda036c'::uuid, '7f8cf438-16d5-5964-8d67-f9c46b05be63'::uuid, 'e5f27a79-6ca6-565f-9a86-77d0ca60d569'::uuid, '951e996a-579e-5e6e-a857-9883bc1caa27'::uuid, 'b88521b1-8e01-5d33-8dfe-e7ff30a1c7da'::uuid, '4e66c36b-520a-569c-9622-3a05ebcc5174'::uuid, '8132146a-a47e-5e7f-a45e-6820075cf86e'::uuid, '6a69cdb1-901d-5618-906a-a52b908d91d0'::uuid, '31730f0a-338e-5b8c-9eff-1cc720558587'::uuid, '0588f5d0-6dad-5ffd-8d3b-1f897f3d6f91'::uuid, '0c3cbc03-a0e7-5887-8160-22c431c91b89'::uuid, 'b9e8feb0-7dbc-57c5-8488-e1c4ba5d2ab3'::uuid, '184cf806-d10c-57cd-8139-5b379917f283'::uuid, '61934f64-7588-5f20-8449-05483bfa0e1f'::uuid, '3e728808-0b70-5007-af74-34c2e81e4936'::uuid, '445275bb-1673-5f50-81f9-a564b2016766'::uuid, '8d141a41-0ab3-5706-b424-aef32d6a85f7'::uuid, '3609536a-a469-54b8-a520-e0a193e294e5'::uuid, '0045491b-43b7-5096-9357-c890f494b759'::uuid, '956de5f5-99ec-5073-ab7e-2135b5312dba'::uuid, '248607ed-c0de-5993-8a0c-e699f3682764'::uuid, '2aa6e1b8-8630-5fc4-86ee-b9466a37c8b0'::uuid, '076ce0c2-a893-52e6-9bf0-75e9adec47fe'::uuid, '4da42dae-a0d5-5b61-af1b-01f40a49af59'::uuid, 'e228533e-5aa9-5bd8-8697-c2dd96334cf6'::uuid, '0065930a-7548-562c-910d-200259206683'::uuid, '67cdd3c7-302a-51fa-a866-4fdea