INSERT INTO stacks (id, market_id, title, stack_type, tags, duration_minutes, published_at, metadata, authored_lesson) VALUES
($ml$daa7d015-941e-547b-bf11-7f5e705bfed0$ml$::uuid, $ml$spacetech$ml$, $ml$Europe's year without a rocket$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-6$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d6-career", "title": "Europe's year without a rocket", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Europe had to rent a rival's rocket.", "eyebrow": "Day 6 · Where it breaks", "headline": "From July 2023 to July 2024, Europe had no rocket of its own for big missions.", "fullText": "Ariane 5 flew for the 117th and last time on July 5, 2023. Russia had already pulled its Soyuz rockets from Europe's spaceport over sanctions after the invasion of Ukraine, and the new Vega-C failed on its first commercial flight. With Ariane 6 four years late, ESA launched its Euclid space telescope on a SpaceX Falcon 9.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]}, {"kind": "microInsight", "id": "squeeze", "eyebrow": "The squeeze", "text": "Europe lost three rockets at once: Ariane 5 retired, Soyuz left and Vega-C failed.", "highlight": "Launches from its Kourou spaceport fell from 15 in 2021 to six in 2022.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "microInsight", "id": "workaround", "eyebrow": "The workaround", "text": "ESA put its Euclid telescope on a SpaceX Falcon 9.", "highlight": "With no option of its own, Europe paid a competitor to fly its science.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "info", "id": "back", "eyebrow": "The return", "title": "Ariane 6 flew in July 2024", "body": "Its first launch, on July 9, 2024, restored Europe's own access to space. The original target had been 2020.", "bullets": ["Six Ariane 6 launches were planned for 2025 and eight for 2026."], "sources": [{"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}, {"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "buildChain", "id": "chain", "prompt": "Put Europe's launch gap in order.", "steps": ["Russia pulls Soyuz from Kourou", "Vega-C fails on its first commercial flight", "Ariane 5 makes its last flight", "Ariane 6 makes its first flight"], "explanation": "Soyuz left in 2022, Vega-C failed that December, Ariane 5 retired in July 2023 and Ariane 6 flew in July 2024."}, {"kind": "theCall", "id": "call", "situation": "You run a European satellite company. Your launch on a European rocket just slipped by a year.", "prompt": "What do you do?", "options": ["Wait for the European rocket, whatever it costs", "Book a backup launch with another provider", "Cancel the satellite and refund your customers"], "consequences": ["A year on the ground is a year with no revenue.", "ESA itself moved Euclid to a Falcon 9 rather than wait.", "Cancelling throws away a satellite you already built."], "correctIndex": 1, "explanation": "One launch option is a single point of failure. Europe learned that in 2023."}, {"id": "lens-career", "kind": "info", "title": "Ask about the backup ride", "body": "Ask which rocket a mission is booked on and what happens if it slips. Europe's 2023 gap shows why it matters.", "eyebrow": "For your interview", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, depending on one launcher is a single point of failure.", "eyebrow": "The rule", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Europe lost Ariane 5, Soyuz and Vega-C at once and launched on SpaceX until Ariane 6 flew in July 2024. Relying on one launcher is a single point of failure.", "sectionKey": "my_view"}]}$ml$::jsonb),
($ml$8d80b9ac-0eea-5d27-b4e8-e06a3a7e73e1$ml$::uuid, $ml$spacetech$ml$, $ml$Europe's year without a rocket$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-6$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:invest$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d6-invest", "title": "Europe's year without a rocket", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Europe had to rent a rival's rocket.", "eyebrow": "Day 6 · Where it breaks", "headline": "From July 2023 to July 2024, Europe had no rocket of its own for big missions.", "fullText": "Ariane 5 flew for the 117th and last time on July 5, 2023. Russia had already pulled its Soyuz rockets from Europe's spaceport over sanctions after the invasion of Ukraine, and the new Vega-C failed on its first commercial flight. With Ariane 6 four years late, ESA launched its Euclid space telescope on a SpaceX Falcon 9.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]}, {"kind": "microInsight", "id": "squeeze", "eyebrow": "The squeeze", "text": "Europe lost three rockets at once: Ariane 5 retired, Soyuz left and Vega-C failed.", "highlight": "Launches from its Kourou spaceport fell from 15 in 2021 to six in 2022.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "microInsight", "id": "workaround", "eyebrow": "The workaround", "text": "ESA put its Euclid telescope on a SpaceX Falcon 9.", "highlight": "With no option of its own, Europe paid a competitor to fly its science.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "info", "id": "back", "eyebrow": "The return", "title": "Ariane 6 flew in July 2024", "body": "Its first launch, on July 9, 2024, restored Europe's own access to space. The original target had been 2020.", "bullets": ["Six Ariane 6 launches were planned for 2025 and eight for 2026."], "sources": [{"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}, {"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "buildChain", "id": "chain", "prompt": "Put Europe's launch gap in order.", "steps": ["Russia pulls Soyuz from Kourou", "Vega-C fails on its first commercial flight", "Ariane 5 makes its last flight", "Ariane 6 makes its first flight"], "explanation": "Soyuz left in 2022, Vega-C failed that December, Ariane 5 retired in July 2023 and Ariane 6 flew in July 2024."}, {"kind": "theCall", "id": "call", "situation": "You run a European satellite company. Your launch on a European rocket just slipped by a year.", "prompt": "What do you do?", "options": ["Wait for the European rocket, whatever it costs", "Book a backup launch with another provider", "Cancel the satellite and refund your customers"], "consequences": ["A year on the ground is a year with no revenue.", "ESA itself moved Euclid to a Falcon 9 rather than wait.", "Cancelling throws away a satellite you already built."], "correctIndex": 1, "explanation": "One launch option is a single point of failure. Europe learned that in 2023."}, {"id": "lens-invest", "kind": "info", "title": "Launch gaps move contracts", "body": "When Europe lost its rockets, missions moved to SpaceX. Gaps like that shift revenue to whoever can fly.", "eyebrow": "For investors", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, depending on one launcher is a single point of failure.", "eyebrow": "The rule", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Europe lost Ariane 5, Soyuz and Vega-C at once and launched on SpaceX until Ariane 6 flew in July 2024. Relying on one launcher is a single point of failure.", "sectionKey": "review"}]}$ml$::jsonb),
($ml$5c2043b4-1298-5139-8669-8721da957115$ml$::uuid, $ml$spacetech$ml$, $ml$Europe's year without a rocket$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-6$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:build_startup$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d6-build_startup", "title": "Europe's year without a rocket", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Europe had to rent a rival's rocket.", "eyebrow": "Day 6 · Where it breaks", "headline": "From July 2023 to July 2024, Europe had no rocket of its own for big missions.", "fullText": "Ariane 5 flew for the 117th and last time on July 5, 2023. Russia had already pulled its Soyuz rockets from Europe's spaceport over sanctions after the invasion of Ukraine, and the new Vega-C failed on its first commercial flight. With Ariane 6 four years late, ESA launched its Euclid space telescope on a SpaceX Falcon 9.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]}, {"kind": "microInsight", "id": "squeeze", "eyebrow": "The squeeze", "text": "Europe lost three rockets at once: Ariane 5 retired, Soyuz left and Vega-C failed.", "highlight": "Launches from its Kourou spaceport fell from 15 in 2021 to six in 2022.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "microInsight", "id": "workaround", "eyebrow": "The workaround", "text": "ESA put its Euclid telescope on a SpaceX Falcon 9.", "highlight": "With no option of its own, Europe paid a competitor to fly its science.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "info", "id": "back", "eyebrow": "The return", "title": "Ariane 6 flew in July 2024", "body": "Its first launch, on July 9, 2024, restored Europe's own access to space. The original target had been 2020.", "bullets": ["Six Ariane 6 launches were planned for 2025 and eight for 2026."], "sources": [{"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}, {"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "buildChain", "id": "chain", "prompt": "Put Europe's launch gap in order.", "steps": ["Russia pulls Soyuz from Kourou", "Vega-C fails on its first commercial flight", "Ariane 5 makes its last flight", "Ariane 6 makes its first flight"], "explanation": "Soyuz left in 2022, Vega-C failed that December, Ariane 5 retired in July 2023 and Ariane 6 flew in July 2024."}, {"kind": "theCall", "id": "call", "situation": "You run a European satellite company. Your launch on a European rocket just slipped by a year.", "prompt": "What do you do?", "options": ["Wait for the European rocket, whatever it costs", "Book a backup launch with another provider", "Cancel the satellite and refund your customers"], "consequences": ["A year on the ground is a year with no revenue.", "ESA itself moved Euclid to a Falcon 9 rather than wait.", "Cancelling throws away a satellite you already built."], "correctIndex": 1, "explanation": "One launch option is a single point of failure. Europe learned that in 2023."}, {"id": "lens-build_startup", "kind": "info", "title": "Independence has buyers", "body": "Europe paid a rival to fly its own science. Customers who need a second way to orbit will pay for one.", "eyebrow": "For founders", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, depending on one launcher is a single point of failure.", "eyebrow": "The rule", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Europe lost Ariane 5, Soyuz and Vega-C at once and launched on SpaceX until Ariane 6 flew in July 2024. Relying on one launcher is a single point of failure.", "sectionKey": "first_test"}]}$ml$::jsonb),
($ml$a4469efe-4ea5-57ef-afb6-081d2bfa707a$ml$::uuid, $ml$spacetech$ml$, $ml$Europe's year without a rocket$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-6$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:curiosity$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d6-curiosity", "title": "Europe's year without a rocket", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Europe had to rent a rival's rocket.", "eyebrow": "Day 6 · Where it breaks", "headline": "From July 2023 to July 2024, Europe had no rocket of its own for big missions.", "fullText": "Ariane 5 flew for the 117th and last time on July 5, 2023. Russia had already pulled its Soyuz rockets from Europe's spaceport over sanctions after the invasion of Ukraine, and the new Vega-C failed on its first commercial flight. With Ariane 6 four years late, ESA launched its Euclid space telescope on a SpaceX Falcon 9.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]}, {"kind": "microInsight", "id": "squeeze", "eyebrow": "The squeeze", "text": "Europe lost three rockets at once: Ariane 5 retired, Soyuz left and Vega-C failed.", "highlight": "Launches from its Kourou spaceport fell from 15 in 2021 to six in 2022.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "microInsight", "id": "workaround", "eyebrow": "The workaround", "text": "ESA put its Euclid telescope on a SpaceX Falcon 9.", "highlight": "With no option of its own, Europe paid a competitor to fly its science.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "info", "id": "back", "eyebrow": "The return", "title": "Ariane 6 flew in July 2024", "body": "Its first launch, on July 9, 2024, restored Europe's own access to space. The original target had been 2020.", "bullets": ["Six Ariane 6 launches were planned for 2025 and eight for 2026."], "sources": [{"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}, {"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"kind": "buildChain", "id": "chain", "prompt": "Put Europe's launch gap in order.", "steps": ["Russia pulls Soyuz from Kourou", "Vega-C fails on its first commercial flight", "Ariane 5 makes its last flight", "Ariane 6 makes its first flight"], "explanation": "Soyuz left in 2022, Vega-C failed that December, Ariane 5 retired in July 2023 and Ariane 6 flew in July 2024."}, {"kind": "theCall", "id": "call", "situation": "You run a European satellite company. Your launch on a European rocket just slipped by a year.", "prompt": "What do you do?", "options": ["Wait for the European rocket, whatever it costs", "Book a backup launch with another provider", "Cancel the satellite and refund your customers"], "consequences": ["A year on the ground is a year with no revenue.", "ESA itself moved Euclid to a Falcon 9 rather than wait.", "Cancelling throws away a satellite you already built."], "correctIndex": 1, "explanation": "One launch option is a single point of failure. Europe learned that in 2023."}, {"id": "lens-curiosity", "kind": "info", "title": "Even agencies need a ride", "body": "Europe's space agency had to launch its telescope on an American rocket. Access to orbit is not guaranteed.", "eyebrow": "Why it matters", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, depending on one launcher is a single point of failure.", "eyebrow": "The rule", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Europe lost Ariane 5, Soyuz and Vega-C at once and launched on SpaceX until Ariane 6 flew in July 2024. Relying on one launcher is a single point of failure.", "sectionKey": "frontier"}]}$ml$::jsonb),
($ml$17478646-1bdd-59ea-b928-d029ba73276d$ml$::uuid, $ml$spacetech$ml$, $ml$Three orbits, three businesses$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-7$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d7-career", "title": "Three orbits, three businesses", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Height decides what a satellite can sell.", "eyebrow": "Day 7 · Orbits", "headline": "A satellite 35,786 km up circles Earth exactly once a day.", "fullText": "Low Earth orbit runs from about 160 to 2,000 km, where a lap takes 90 minutes to 2 hours. GPS satellites sit in medium orbit near 20,000 km and circle about twice a day. At 35,786 km, a lap matches Earth's spin, so a geostationary satellite seems to hang over one spot.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "microInsight", "id": "leo", "eyebrow": "Low Earth orbit", "text": "Low orbit is close and fast: a lap takes 90 minutes to 2 hours.", "highlight": "Iridium's 66 phone satellites fly at about 780 km.", "keyTerms": [{"term": "LEO", "definition": "Low Earth orbit, about 160 to 2,000 km up."}], "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "microInsight", "id": "meo", "eyebrow": "Medium Earth orbit", "text": "Medium orbit is home to navigation: GPS flies at about 20,000 km.", "highlight": "A lap there takes about 12 hours.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "info", "id": "geo", "eyebrow": "Geostationary orbit", "title": "Geostationary satellites hover over one spot", "body": "At 35,786 km a lap takes one day, so a dish on the ground can point at one fixed place.", "bullets": ["One geostationary satellite sees about a third of the planet."], "keyTerms": [{"term": "GEO", "definition": "Geostationary orbit, 35,786 km up, where a lap takes one day."}], "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "Match each job to its orbit.", "buckets": ["Low", "Medium", "Geostationary"], "items": [{"text": "Space station crew lab", "bucket": 0}, {"text": "Iridium satellite phones", "bucket": 0}, {"text": "GPS navigation", "bucket": 1}, {"text": "DISH TV broadcasting", "bucket": 2}, {"text": "Intelsat communications", "bucket": 2}], "explanation": "Crewed labs and phone networks fly low, GPS sits in medium orbit, and broadcasters use geostationary orbit."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why can a home TV dish stay pointed at one spot in the sky?", "options": ["A motor in the dish keeps tracking it", "It flies low enough to stay in view", "Its orbit takes exactly one day"], "correctIndex": 2, "explanation": "At 35,786 km the orbit matches Earth's spin, so the satellite stays over one place."}, {"id": "lens-career", "kind": "info", "title": "Know the orbit before the company", "body": "Say which orbit a company works in. Low, medium and geostationary mean different products, customers and risks.", "eyebrow": "For your interview", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, the orbit you choose decides what you can sell.", "eyebrow": "The rule", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Low orbit is close and fast, GPS sits in medium orbit near 20,000 km, and geostationary satellites at 35,786 km hover over one spot. The orbit decides the business.", "sectionKey": "players"}]}$ml$::jsonb),
