($ml$28a8fdd2-08d7-517b-9137-671ddbdc40c3$ml$::uuid, $ml$spacetech$ml$, $ml$Three orbits, three businesses$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-7$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:curiosity$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d7-curiosity", "title": "Three orbits, three businesses", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Height decides what a satellite can sell.", "eyebrow": "Day 7 · Orbits", "headline": "A satellite 35,786 km up circles Earth exactly once a day.", "fullText": "Low Earth orbit runs from about 160 to 2,000 km, where a lap takes 90 minutes to 2 hours. GPS satellites sit in medium orbit near 20,000 km and circle about twice a day. At 35,786 km, a lap matches Earth's spin, so a geostationary satellite seems to hang over one spot.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "microInsight", "id": "leo", "eyebrow": "Low Earth orbit", "text": "Low orbit is close and fast: a lap takes 90 minutes to 2 hours.", "highlight": "Iridium's 66 phone satellites fly at about 780 km.", "keyTerms": [{"term": "LEO", "definition": "Low Earth orbit, about 160 to 2,000 km up."}], "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "microInsight", "id": "meo", "eyebrow": "Medium Earth orbit", "text": "Medium orbit is home to navigation: GPS flies at about 20,000 km.", "highlight": "A lap there takes about 12 hours.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "info", "id": "geo", "eyebrow": "Geostationary orbit", "title": "Geostationary satellites hover over one spot", "body": "At 35,786 km a lap takes one day, so a dish on the ground can point at one fixed place.", "bullets": ["One geostationary satellite sees about a third of the planet."], "keyTerms": [{"term": "GEO", "definition": "Geostationary orbit, 35,786 km up, where a lap takes one day."}], "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "Match each job to its orbit.", "buckets": ["Low", "Medium", "Geostationary"], "items": [{"text": "Space station crew lab", "bucket": 0}, {"text": "Iridium satellite phones", "bucket": 0}, {"text": "GPS navigation", "bucket": 1}, {"text": "DISH TV broadcasting", "bucket": 2}, {"text": "Intelsat communications", "bucket": 2}], "explanation": "Crewed labs and phone networks fly low, GPS sits in medium orbit, and broadcasters use geostationary orbit."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why can a home TV dish stay pointed at one spot in the sky?", "options": ["A motor in the dish keeps tracking it", "It flies low enough to stay in view", "Its orbit takes exactly one day"], "correctIndex": 2, "explanation": "At 35,786 km the orbit matches Earth's spin, so the satellite stays over one place."}, {"id": "lens-curiosity", "kind": "info", "title": "Height sets the clock", "body": "The higher the orbit, the longer the lap: 90 minutes low, about 12 hours for GPS, a full day at 35,786 km.", "eyebrow": "Why it matters", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, the orbit you choose decides what you can sell.", "eyebrow": "The rule", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Low orbit is close and fast, GPS sits in medium orbit near 20,000 km, and geostationary satellites at 35,786 km hover over one spot. The orbit decides the business.", "sectionKey": "basics"}]}$ml$::jsonb),
($ml$c651c3e2-ada6-5bab-88e9-540e8ed31976$ml$::uuid, $ml$spacetech$ml$, $ml$Why low orbit needs thousands of satellites$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-8$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d8-career", "title": "Why low orbit needs thousands of satellites", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A handful of satellites, or thousands.", "eyebrow": "Day 8 · The money", "headline": "One geostationary satellite sees a third of Earth. Starlink flies about 9,400.", "fullText": "A satellite at 35,786 km sees about a third of the planet, so a handful can serve whole continents. A low satellite sees a small patch and races past it in minutes, so a network needs many more to keep a customer connected. Starlink had roughly 9,400 active satellites in early 2026.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"kind": "microInsight", "id": "delay", "eyebrow": "The delay", "text": "The trade is distance for delay.", "highlight": "Up to a geostationary satellite and back down is about 71,600 km: a quarter of a second, even at light speed.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "microInsight", "id": "bill", "eyebrow": "The bill", "text": "Low orbit cuts the delay but multiplies the hardware bill.", "highlight": "Each low satellite only serves customers while it passes over them.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "info", "id": "two-ways", "eyebrow": "Two models", "title": "Two ways to cover the planet", "body": "Geostationary: a few large satellites far away. Low orbit: many satellites close by, each in view for minutes.", "bullets": ["Iridium covers the globe with 66 satellites at about 780 km."], "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "numberSense", "id": "ns-delay", "prompt": "A signal travels about 71,600 km up to a geostationary satellite and back down. At 300,000 km per second, how many milliseconds does that take?", "min": 0, "max": 1000, "value": 240, "unit": "ms", "explanation": "71,600 ÷ 300,000 is about 0.24 seconds, or 240 ms, before any processing. Low orbit is dozens of times closer."}, {"kind": "faceOff", "id": "face", "prompt": "Which network needs more satellites to serve the same customers?", "left": {"name": "Geostationary network", "note": "Satellites at 35,786 km"}, "right": {"name": "Low-orbit network", "note": "Satellites below 2,000 km"}, "correctIndex": 1, "explanation": "Low satellites each see a small patch and pass quickly, so you need many more of them."}, {"id": "lens-career", "kind": "info", "title": "Explain the latency trade", "body": "Be ready to explain why low orbit means less delay but far more satellites. It is the core trade in satellite internet.", "eyebrow": "For your interview", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, closer satellites are faster, but you need far more of them.", "eyebrow": "The rule", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "A geostationary satellite covers a third of Earth but a signal needs about a quarter second to go up and back. Low orbit is fast but needs thousands of satellites, like Starlink's roughly 9,400.", "sectionKey": "how_money_moves"}]}$ml$::jsonb),
($ml$a0212085-abf4-5e4b-9a31-50ba19dacf00$ml$::uuid, $ml$spacetech$ml$, $ml$Why low orbit needs thousands of satellites$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-8$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:invest$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d8-invest", "title": "Why low orbit needs thousands of satellites", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A handful of satellites, or thousands.", "eyebrow": "Day 8 · The money", "headline": "One geostationary satellite sees a third of Earth. Starlink flies about 9,400.", "fullText": "A satellite at 35,786 km sees about a third of the planet, so a handful can serve whole continents. A low satellite sees a small patch and races past it in minutes, so a network needs many more to keep a customer connected. Starlink had roughly 9,400 active satellites in early 2026.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"kind": "microInsight", "id": "delay", "eyebrow": "The delay", "text": "The trade is distance for delay.", "highlight": "Up to a geostationary satellite and back down is about 71,600 km: a quarter of a second, even at light speed.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "microInsight", "id": "bill", "eyebrow": "The bill", "text": "Low orbit cuts the delay but multiplies the hardware bill.", "highlight": "Each low satellite only serves customers while it passes over them.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "info", "id": "two-ways", "eyebrow": "Two models", "title": "Two ways to cover the planet", "body": "Geostationary: a few large satellites far away. Low orbit: many satellites close by, each in view for minutes.", "bullets": ["Iridium covers the globe with 66 satellites at about 780 km."], "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "numberSense", "id": "ns-delay", "prompt": "A signal travels about 71,600 km up to a geostationary satellite and back down. At 300,000 km per second, how many milliseconds does that take?", "min": 0, "max": 1000, "value": 240, "unit": "ms", "explanation": "71,600 ÷ 300,000 is about 0.24 seconds, or 240 ms, before any processing. Low orbit is dozens of times closer."}, {"kind": "faceOff", "id": "face", "prompt": "Which network needs more satellites to serve the same customers?", "left": {"name": "Geostationary network", "note": "Satellites at 35,786 km"}, "right": {"name": "Low-orbit network", "note": "Satellites below 2,000 km"}, "correctIndex": 1, "explanation": "Low satellites each see a small patch and pass quickly, so you need many more of them."}, {"id": "lens-invest", "kind": "info", "title": "More satellites, more capital", "body": "A low-orbit network needs thousands of satellites before it can serve everyone. Ask how it pays for them.", "eyebrow": "For investors", "sources": [{"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, closer satellites are faster, but you need far more of them.", "eyebrow": "The rule", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "A geostationary satellite covers a third of Earth but a signal needs about a quarter second to go up and back. Low orbit is fast but needs thousands of satellites, like Starlink's roughly 9,400.", "sectionKey": "drivers"}]}$ml$::jsonb),
($ml$440d1c24-e778-53d9-8c1d-938797b19054$ml$::uuid, $ml$spacetech$ml$, $ml$Why low orbit needs thousands of satellites$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-8$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:build_startup$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d8-build_startup", "title": "Why low orbit needs thousands of satellites", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A handful of satellites, or thousands.", "eyebrow": "Day 8 · The money", "headline": "One geostationary satellite sees a third of Earth. Starlink flies about 9,400.", "fullText": "A satellite at 35,786 km sees about a third of the planet, so a handful can serve whole continents. A low satellite sees a small patch and races past it in minutes, so a network needs many more to keep a customer connected. Starlink had roughly 9,400 active satellites in early 2026.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"kind": "microInsight", "id": "delay", "eyebrow": "The delay", "text": "The trade is distance for delay.", "highlight": "Up to a geostationary satellite and back down is about 71,600 km: a quarter of a second, even at light speed.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "microInsight", "id": "bill", "eyebrow": "The bill", "text": "Low orbit cuts the delay but multiplies the hardware bill.", "highlight": "Each low satellite only serves customers while it passes over them.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "info", "id": "two-ways", "eyebrow": "Two models", "title": "Two ways to cover the planet", "body": "Geostationary: a few large satellites far away. Low orbit: many satellites close by, each in view for minutes.", "bullets": ["Iridium covers the globe with 66 satellites at about 780 km."], "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"kind": "numberSense", "id": "ns-delay", "prompt": "A signal travels about 71,600 km up to a geostationary satellite and back down. At 300,000 km per second, how many milliseconds does that take?", "min": 0, "max": 1000, "value": 240, "unit": "ms", "explanation": "71,600 ÷ 300,000 is about 0.24 seconds, or 240 ms, before any processing. Low orbit is dozens of times closer."}, {"kind": "faceOff", "id": "face", "prompt": "Which network needs more satellites to serve the same customers?", "left": {"name": "Geostationary network", "note": "Satellites at 35,786 km"}, "right": {"name": "Low-orbit network", "note": "Satellites below 2,000 km"}, "correctIndex": 1, "explanation": "Low satellites each see a small patch and pass quickly, so you need many more of them."}, {"id": "lens-build_startup", "kind": "info", "title": "Find who needs fast links", "body": "Low delay matters for calls and gaming. Wide, slower coverage from far away still suits TV broadcasting.", "eyebrow": "For founders", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, closer satellites are faster, but you need far more of them.", "eyebrow": "The rule", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "A geostationary satellite covers a third of Earth but a signal needs about a quarter second to go up and back. Low orbit is fast but needs thousands of satellites, like Starlink's roughly 9,400.", "sectionKey": "gap"}]}$ml$::jsonb),
