($ml$b88521b1-8e01-5d33-8dfe-e7ff30a1c7da$ml$::uuid, $ml$spacetech$ml$, $ml$The storm that sank 38 satellites$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-11$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d11-career", "title": "The storm that sank 38 satellites", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A minor storm, a major loss.", "eyebrow": "Day 11 · The risk", "headline": "In February 2022, a geomagnetic storm brought down 38 of 49 new Starlink satellites.", "fullText": "SpaceX launched 49 Starlink satellites on February 3, 2022. Solar plasma from a geomagnetic storm heated the upper atmosphere, and denser gas expanded into the satellites' orbit. Drag rose, and 38 of them reentered and burned up within days. Forecasters had expected only minor storming.", "sources": [{"url": "https://svs.gsfc.nasa.gov/hyperwall/index/data/a000000/a005100/a005193/cap5193.txt.html", "label": "NASA, geomagnetic storm causes Starlink loss"}, {"url": "https://cires.colorado.edu/news/minor-geomagnetic-storm-big-impact-february-2022-starlink-satellite-loss", "label": "CIRES, minor storm, big impact"}]}, {"kind": "microInsight", "id": "physics", "eyebrow": "The physics", "text": "Low orbit is not empty: thin air still drags on satellites.", "highlight": "When the Sun heats it, that air swells upward and drag rises.", "keyTerms": [{"term": "Drag", "definition": "The push of thin air against a satellite, which slowly lowers its orbit."}], "sources": [{"url": "https://svs.gsfc.nasa.gov/hyperwall/index/data/a000000/a005100/a005193/cap5193.txt.html", "label": "NASA, geomagnetic storm causes Starlink loss"}]}, {"kind": "microInsight", "id": "surprise", "eyebrow": "The surprise", "text": "The forecast called it minor.", "highlight": "A small storm was enough to wipe out most of a launch.", "sources": [{"url": "https://cires.colorado.edu/news/minor-geomagnetic-storm-big-impact-february-2022-starlink-satellite-loss", "label": "CIRES, minor storm, big impact"}]}, {"kind": "info", "id": "both-ways", "eyebrow": "The trade-off", "title": "Drag cuts both ways", "body": "It pulls dead satellites down, which keeps low orbit cleaner. It also pulls down working ones that cannot push back.", "sources": [{"url": "https://svs.gsfc.nasa.gov/hyperwall/index/data/a000000/a005100/a005193/cap5193.txt.html", "label": "NASA, geomagnetic storm causes Starlink loss"}]}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["The storm made the upper air thinner, so drag dropped.", "38 of 49 satellites were lost after a February 2022 launch.", "Forecasters had expected only minor storming."], "fakeIndex": 0, "explanation": "The opposite: heated gas expanded upward, so the air in their orbit got denser and drag rose."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why did the storm bring the satellites down?", "options": ["Radiation damaged their computers", "Denser air raised the drag on them", "Storm debris collided with them"], "correctIndex": 1, "explanation": "The storm heated the upper atmosphere, gas expanded into their orbit, and drag pulled them down."}, {"id": "lens-career", "kind": "info", "title": "Space weather is an ops topic", "body": "Since 2022, space weather is part of planning any low-orbit launch. Explaining why shows you think like an operator.", "eyebrow": "For your interview", "sources": [{"url": "https://svs.gsfc.nasa.gov/hyperwall/index/data/a000000/a005100/a005193/cap5193.txt.html", "label": "NASA, geomagnetic storm causes Starlink loss"}, {"url": "https://cires.colorado.edu/news/minor-geomagnetic-storm-big-impact-february-2022-starlink-satellite-loss", "label": "CIRES, minor storm, big impact"}]}, {"id": "rule", "kind": "microInsight", "text": "In low orbit, the Sun's weather can decide whether a satellite survives.", "eyebrow": "The rule", "sources": [{"url": "https://svs.gsfc.nasa.gov/hyperwall/index/data/a000000/a005100/a005193/cap5193.txt.html", "label": "NASA, geomagnetic storm causes Starlink loss"}, {"url": "https://cires.colorado.edu/news/minor-geomagnetic-storm-big-impact-february-2022-starlink-satellite-loss", "label": "CIRES, minor storm, big impact"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "In February 2022, a minor geomagnetic storm swelled the upper atmosphere and drag brought down 38 of 49 new Starlink satellites. Space weather is a real operating risk.", "sectionKey": "risk"}]}$ml$::jsonb),
