($ml$31730f0a-338e-5b8c-9eff-1cc720558587$ml$::uuid, $ml$spacetech$ml$, $ml$300,000 swerves in a year$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-12$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d12-career", "title": "300,000 swerves in a year", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Low orbit is getting crowded fast.", "eyebrow": "Day 12 · Where it breaks", "headline": "Starlink satellites made about 300,000 collision-avoidance maneuvers in 2025.", "fullText": "SpaceX told the FCC its satellites dodged roughly 300,000 possible collisions in 2025, nearly 40 per satellite. In the six months to May 2023 the count was about 25,000. SpaceX moves when collision risk reaches about three in ten million, far more cautious than the common one-in-10,000 threshold.", "sources": [{"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}, {"url": "https://space.com/spacex-starlink-50000-collision-avoidance-maneuvers-space-safety", "label": "Space.com, 50,000 maneuvers in six months"}]}, {"kind": "microInsight", "id": "trend", "eyebrow": "The trend", "text": "Maneuvers doubled from about 25,000 to nearly 50,000 in one half-year.", "highlight": "That was December 2023 to May 2024, as the fleet grew from about 5,100 to 6,200 satellites.", "sources": [{"url": "https://space.com/spacex-starlink-50000-collision-avoidance-maneuvers-space-safety", "label": "Space.com, 50,000 maneuvers in six months"}]}, {"kind": "microInsight", "id": "cost", "eyebrow": "The cost", "text": "Every swerve uses fuel and needs a decision.", "highlight": "At this pace, maneuvers could near one million a year by 2027.", "sources": [{"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"kind": "info", "id": "threshold", "eyebrow": "Who decides", "title": "Each operator sets its own threshold", "body": "Operators choose when a close pass is worth a move. SpaceX moves at three in ten million; the common standard is one in 10,000.", "sources": [{"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"kind": "numberSense", "id": "ns-moves", "prompt": "About how many collision-avoidance maneuvers did Starlink make in 2025, in thousands?", "min": 0, "max": 800, "value": 300, "unit": "k", "explanation": "About 300,000, nearly 40 per satellite."}, {"kind": "theCall", "id": "call", "situation": "You run a 300-satellite network. A Starlink satellite may pass close to one of yours tomorrow.", "prompt": "What do you do?", "options": ["Assume they will dodge and do nothing", "Contact SpaceX and agree on who moves", "Move every satellite to a new orbit"], "consequences": ["If both sides assume the other moves, nobody does.", "Agreeing who moves avoids a double swerve, or none at all.", "Moving a whole fleet burns fuel over one close pass."], "correctIndex": 1, "explanation": "Close passes are routine now. Talking to the other operator avoids both of you moving, or neither."}, {"id": "lens-career", "kind": "info", "title": "Know the traffic numbers", "body": "Quote the trend: about 25,000 Starlink maneuvers in six months to May 2023, about 300,000 in 2025. It shows you track the real risk.", "eyebrow": "For your interview", "sources": [{"url": "https://space.com/spacex-starlink-50000-collision-avoidance-maneuvers-space-safety", "label": "Space.com, 50,000 maneuvers in six months"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, crowded orbits turn safety into a daily operating cost.", "eyebrow": "The rule", "sources": [{"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}, {"url": "https://space.com/spacex-starlink-50000-collision-avoidance-maneuvers-space-safety", "label": "Space.com, 50,000 maneuvers in six months"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Starlink made about 300,000 collision-avoidance maneuvers in 2025, up from about 25,000 per half-year in 2023. Each operator sets its own risk threshold.", "sectionKey": "my_view"}]}$ml$::jsonb),
