($ml$184cf806-d10c-57cd-8139-5b379917f283$ml$::uuid, $ml$spacetech$ml$, $ml$What reuse really reuses$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-13$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d13-career", "title": "What reuse really reuses", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Most of a Falcon 9 comes home.", "eyebrow": "Day 13 · Reuse", "headline": "In 2025, 157 of 165 Falcon 9 launches flew on boosters that had flown before.", "fullText": "The first stage flies back, lands and is used again. Payload fairing halves are recovered and reflown on many missions. The second stage, which pushes the payload into orbit, is thrown away every time. In 2025 boosters came back on all but three of the 165 flights.", "sources": [{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]}, {"kind": "microInsight", "id": "booster", "eyebrow": "What comes back", "text": "The booster is the biggest part of the rocket, and it lands.", "highlight": "In 2025 boosters returned on all but three missions, two of them expended on purpose.", "sources": [{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]}, {"kind": "microInsight", "id": "upper", "eyebrow": "What doesn't", "text": "The second stage is lost on every flight.", "highlight": "It is the part that reaches orbit, so it has no easy way home.", "keyTerms": [{"term": "Second stage", "definition": "The upper part of a rocket that pushes the payload the rest of the way to orbit."}], "sources": [{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]}, {"kind": "info", "id": "routine", "eyebrow": "The record", "title": "Reuse is now routine", "body": "Falcon 9 had flown about 620 times by March 2026, with a mission success rate above 99%.", "bullets": ["All 165 of its 2025 launches delivered their payloads."], "sources": [{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "On a Falcon 9, reused or thrown away?", "buckets": ["Usually reused", "Thrown away"], "items": [{"text": "First-stage booster", "bucket": 0}, {"text": "Payload fairing halves", "bucket": 0}, {"text": "Second stage", "bucket": 1}, {"text": "Second-stage engine", "bucket": 1}], "explanation": "The booster and often the fairings fly again. The second stage, engine included, is expended."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why is the second stage the hardest part to bring back?", "options": ["It is the most expensive part of the rocket", "It reaches orbit, so it has no easy way home", "Regulators do not allow anyone to reuse it"], "correctIndex": 1, "explanation": "The booster turns around before orbit. The second stage ends up in orbit, far from the pad and moving fast."}, {"id": "lens-career", "kind": "info", "title": "Say what reuse actually saves", "body": "Reuse means the booster and often the fairings fly again, not the whole rocket. Saying it precisely sounds like an insider.", "eyebrow": "For your interview", "sources": [{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]}, {"id": "rule", "kind": "microInsight", "text": "In launch, whatever you throw away sets your cost floor.", "eyebrow": "The rule", "sources": [{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Falcon 9 reuses its booster and often its fairings, but throws away the second stage. In 2025, 157 of 165 launches used boosters that had flown before.", "sectionKey": "players"}]}$ml$::jsonb),
