y/2024/05/01/slingshot-aerospace-reveals-record-insurance-losses-in-2023-in-new-satellite-deployments-report", "label": "Via Satellite, record space insurance losses in 2023"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, insurers price the risk, and one bad year resets the price for everyone.", "eyebrow": "The rule", "sources": [{"url": "https://www.satellitetoday.com/sustainability/2024/05/01/slingshot-aerospace-reveals-record-insurance-losses-in-2023-in-new-satellite-deployments-report", "label": "Via Satellite, record space insurance losses in 2023"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "In 2023, insurers paid $995 million in space claims against about $557 million in premiums. Rates for a geostationary satellite rose from under 6% to about 10%.", "sectionKey": "chain"}]}$ml$::jsonb),
($ml$248607ed-c0de-5993-8a0c-e699f3682764$ml$::uuid, $ml$spacetech$ml$, $ml$The customer that decides who survives$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-15$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d15-career", "title": "The customer that decides who survives", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "One buyer split 54 missions three ways.", "eyebrow": "Day 15 · The power", "headline": "In April 2025, the Space Force gave SpaceX 28 national security launches, ULA 19 and Blue Origin 7.", "fullText": "The awards cover the hardest missions in Phase 3, Lane 2 of the National Security Space Launch program, with ceilings of more than $5.9 billion for SpaceX, more than $5.3 billion for ULA and nearly $2.4 billion for Blue Origin. US law requires keeping at least two launch vehicles able to carry any national security payload.", "sources": [{"url": "https://www.satellitetoday.com/launch/2025/04/06/spacex-ula-blue-origin-receive-nssl-contracts-worth-up-to-nearly-14b/", "label": "Via Satellite, NSSL Phase 3 Lane 2 awards"}, {"url": "https://www.everycrsreport.com/files/2026-01-14_IF12900_e1a9a9283349423491e151fac8e59426a6fa6708.html", "label": "Congressional Research Service, NSSL primer"}]}, {"kind": "microInsight", "id": "buyer", "eyebrow": "The buyer", "text": "National security launches are a small market with a big say.", "highlight": "54 missions in this lane, spread across three companies.", "sources": [{"url": "https://www.satellitetoday.com/launch/2025/04/06/spacex-ula-blue-origin-receive-nssl-contracts-worth-up-to-nearly-14b/", "label": "Via Satellite, NSSL Phase 3 Lane 2 awards"}]}, {"kind": "microInsight", "id": "stakes", "eyebrow": "The stakes", "text": "Winning the work keeps a launcher busy for years.", "highlight": "The Phase 3 plan covers 84 missions from fiscal 2025 through 2029.", "sources": [{"url": "https://www.satellitetoday.com/launch/2025/04/06/spacex-ula-blue-origin-receive-nssl-contracts-worth-up-to-nearly-14b/", "label": "Via Satellite, NSSL Phase 3 Lane 2 awards"}]}, {"kind": "info", "id": "two-rockets", "eyebrow": "The rule behind it", "title": "Why the work is split", "body": "Congress made it policy to keep at least two launch vehicles that can carry any national security payload. If one is grounded, the other still flies.", "sources": [{"url": "https://www.everycrsreport.com/files/2026-01-14_IF12900_e1a9a9283349423491e151fac8e59426a6fa6708.html", "label": "Congressional Research Service, NSSL primer"}]}, {"kind": "faceOff", "id": "face", "prompt": "Who holds more power in this market?", "left": {"name": "The Space Force", "note": "Picks who flies its 54 hardest missions"}, "right": {"name": "One launch company", "note": "Needs those missions to keep busy"}, "correctIndex": 0, "explanation": "The buyer chooses among providers. Each provider needs the buyer more than the reverse."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why didn't the Space Force give all 54 missions to one provider?", "options": ["SpaceX could not build enough rockets", "The law caps each company at ten missions", "It must keep two ways to reach orbit"], "correctIndex": 2, "explanation": "US policy requires at least two launch vehicles that can carry any national security payload."}, {"id": "lens-career", "kind": "info", "title": "Know the anchor customers", "body": "Name who buys a launch company's flights. National security work comes with strict rules and long timelines.", "eyebrow": "For your interview", "sources": [{"url": "https://www.satellitetoday.com/launch/2025/04/06/spacex-ula-blue-origin-receive-nssl-contracts-worth-up-to-nearly-14b/", "label": "Via Satellite, NSSL Phase 3 Lane 2 awards"}, {"url": "https://www.everycrsreport.com/files/2026-01-14_IF12900_e1a9a9283349423491e151fac8e59426a6fa6708.html", "label": "Congressional Research Service, NSSL primer"}]}, {"id": "rule", "kind": "microInsight", "text": "In launch, an anchor customer can decide who survives.", "eyebrow": "The rule", "sources": [{"url": "https://www.satellitetoday.com/launch/2025/04/06/spacex-ula-blue-origin-receive-nssl-contracts-worth-up-to-nearly-14b/", "label": "Via Satellite, NSSL Phase 3 Lane 2 awards"}, {"url": "https://www.everycrsreport.com/files/2026-01-14_IF12900_e1a9a9283349423491e151fac8e59426a6fa6708.html", "label": "Congressional Research Service, NSSL primer"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "In April 2025 the Space Force split 54 national security launches between SpaceX, ULA and Blue Origin. US policy requires at least two launch vehicles, so it never depends on one rocket.", "sectionKey": "questions"}]}$ml$::jsonb),
