($ml$7ecef5c7-ed6d-5fd9-bd68-0bbb4416e1dd$ml$::uuid, $ml$spacetech$ml$, $ml$What a space agency actually does$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-19$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d19-career", "title": "What a space agency actually does", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Agencies mostly buy, not build.", "eyebrow": "Day 19 · Agencies", "headline": "ESA's 2025 budget was €7.7 billion, with €4.8 billion from its member states.", "fullText": "The European Union added €1.7 billion and other sources €1.2 billion. ESA spends it as a customer, placing contracts with companies across its member states. NASA works the same way at a larger scale: Congress passed $24.4 billion for it in fiscal 2026.", "sources": [{"url": "https://aviationweek.com/space/budget-policy-regulation/esa-council-oks-initial-eu77b-2025-budget-readies-launcher-challenge", "label": "Aviation Week, ESA 2025 budget"}, {"url": "https://www.esa.int/About_Us/Business_with_ESA/Business_Opportunities/ESA_an_intergovernmental_customer", "label": "ESA, an intergovernmental customer"}, {"url": "https://space.com/space-exploration/in-rejection-of-trumps-deep-cuts-congress-passes-usd24-4-billion-budget-for-nasa", "label": "Space.com, NASA fiscal 2026 budget"}]}, {"kind": "microInsight", "id": "customer", "eyebrow": "The role", "text": "A space agency is mostly a customer: it pays companies to build what it plans.", "highlight": "ESA describes itself as an intergovernmental customer.", "keyTerms": [{"term": "Space agency", "definition": "A government body that plans space programs and pays companies to carry them out."}], "sources": [{"url": "https://www.esa.int/About_Us/Business_with_ESA/Business_Opportunities/ESA_an_intergovernmental_customer", "label": "ESA, an intergovernmental customer"}]}, {"kind": "microInsight", "id": "scale", "eyebrow": "The scale", "text": "NASA's budget is about three times ESA's.", "highlight": "$24.4 billion for fiscal 2026, against €7.7 billion for ESA in 2025.", "sources": [{"url": "https://space.com/space-exploration/in-rejection-of-trumps-deep-cuts-congress-passes-usd24-4-billion-budget-for-nasa", "label": "Space.com, NASA fiscal 2026 budget"}, {"url": "https://aviationweek.com/space/budget-policy-regulation/esa-council-oks-initial-eu77b-2025-budget-readies-launcher-challenge", "label": "Aviation Week, ESA 2025 budget"}]}, {"kind": "info", "id": "agenda", "eyebrow": "Why it matters", "title": "Agency plans become industry work", "body": "When an agency starts a program, the money turns into multi-year contracts for companies.", "bullets": ["Member states provided €4.8 billion of ESA's 2025 budget."], "sources": [{"url": "https://www.esa.int/About_Us/Business_with_ESA/Business_Opportunities/ESA_an_intergovernmental_customer", "label": "ESA, an intergovernmental customer"}, {"url": "https://aviationweek.com/space/budget-policy-regulation/esa-council-oks-initial-eu77b-2025-budget-readies-launcher-challenge", "label": "Aviation Week, ESA 2025 budget"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "NASA or ESA?", "buckets": ["NASA", "ESA"], "items": [{"text": "Funded by Congress each year", "bucket": 0}, {"text": "$24.4 billion for fiscal 2026", "bucket": 0}, {"text": "Funded by member states and the EU", "bucket": 1}, {"text": "€7.7 billion budget in 2025", "bucket": 1}], "explanation": "NASA is funded by Congress. ESA is funded by its member states, the EU and other sources."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Where does most of a space agency's budget go?", "options": ["Contracts with companies", "Running its own factories", "Buying shares in startups"], "correctIndex": 0, "explanation": "Agencies plan programs and pay companies to build and fly them."}, {"id": "lens-career", "kind": "info", "title": "Follow the agency contracts", "body": "Many space jobs exist because an agency funded a program. Ask which agency contract a team works under.", "eyebrow": "For your interview", "sources": [{"url": "https://www.esa.int/About_Us/Business_with_ESA/Business_Opportunities/ESA_an_intergovernmental_customer", "label": "ESA, an intergovernmental customer"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, agencies set the plans and industry builds them.", "eyebrow": "The rule", "sources": [{"url": "https://www.esa.int/About_Us/Business_with_ESA/Business_Opportunities/ESA_an_intergovernmental_customer", "label": "ESA, an intergovernmental customer"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Space agencies are mainly customers: ESA had €7.7 billion in 2025 and NASA $24.4 billion for fiscal 2026, spent largely through contracts with companies.", "sectionKey": "players"}]}$ml$::jsonb),
