($ml$897472e1-fa67-5270-b885-0f1c750c50be$ml$::uuid, $ml$spacetech$ml$, $ml$Why NASA paid for two Moon landers$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-21$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d21-career", "title": "Why NASA paid for two Moon landers", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "The buyer kept a second option.", "eyebrow": "Day 21 · The power", "headline": "In May 2023, NASA gave Blue Origin $3.4 billion to build a second crewed Moon lander.", "fullText": "SpaceX had won the first lander contract in 2021 with a $2.9 billion bid for Starship. NASA then paid for a second design so it would have redundancy and competition for long-term Moon missions. Blue Origin's first crewed landing was planned for Artemis V.", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"kind": "microInsight", "id": "one-vs-two", "eyebrow": "The logic", "text": "With one supplier, the supplier holds the cards.", "highlight": "With two, NASA can push both on price and schedule.", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"kind": "microInsight", "id": "skin", "eyebrow": "Who pays", "text": "Blue Origin is putting in money of its own too.", "highlight": "The total effort is estimated at about $7 billion.", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"kind": "info", "id": "price", "eyebrow": "The trade-off", "title": "Redundancy has a price", "body": "Paying for two landers costs more up front. NASA judged it worth it to avoid depending on one company.", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"kind": "faceOff", "id": "face", "prompt": "After NASA picked a second lander, who gained bargaining power?", "left": {"name": "NASA", "note": "Now has two lander suppliers"}, "right": {"name": "SpaceX", "note": "No longer the only lander supplier"}, "correctIndex": 0, "explanation": "A buyer with a backup can push each supplier harder."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why did NASA fund a second Moon lander?", "options": ["For redundancy and competition", "SpaceX's design failed its review", "Congress banned single bids"], "correctIndex": 0, "explanation": "NASA said it wanted two providers for redundancy and competition on long-term Moon missions."}, {"id": "lens-career", "kind": "info", "title": "Know why NASA buys twice", "body": "NASA paid for two landers to keep redundancy and competition. Explaining that shows procurement sense.", "eyebrow": "For your interview", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"id": "rule", "kind": "microInsight", "text": "In space exploration, paying for a second supplier buys the buyer bargaining power.", "eyebrow": "The rule", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "NASA paid Blue Origin $3.4 billion in 2023 for a second Moon lander after SpaceX's 2021 win. Two suppliers give NASA redundancy and competition.", "sectionKey": "questions"}]}$ml$::jsonb),
