($ml$57139de0-4ca8-5bb0-b1f6-0c9267615464$ml$::uuid, $ml$spacetech$ml$, $ml$Why NASA paid for two Moon landers$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-21$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:curiosity$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d21-curiosity", "title": "Why NASA paid for two Moon landers", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "The buyer kept a second option.", "eyebrow": "Day 21 · The power", "headline": "In May 2023, NASA gave Blue Origin $3.4 billion to build a second crewed Moon lander.", "fullText": "SpaceX had won the first lander contract in 2021 with a $2.9 billion bid for Starship. NASA then paid for a second design so it would have redundancy and competition for long-term Moon missions. Blue Origin's first crewed landing was planned for Artemis V.", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"kind": "microInsight", "id": "one-vs-two", "eyebrow": "The logic", "text": "With one supplier, the supplier holds the cards.", "highlight": "With two, NASA can push both on price and schedule.", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"kind": "microInsight", "id": "skin", "eyebrow": "Who pays", "text": "Blue Origin is putting in money of its own too.", "highlight": "The total effort is estimated at about $7 billion.", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"kind": "info", "id": "price", "eyebrow": "The trade-off", "title": "Redundancy has a price", "body": "Paying for two landers costs more up front. NASA judged it worth it to avoid depending on one company.", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"kind": "faceOff", "id": "face", "prompt": "After NASA picked a second lander, who gained bargaining power?", "left": {"name": "NASA", "note": "Now has two lander suppliers"}, "right": {"name": "SpaceX", "note": "No longer the only lander supplier"}, "correctIndex": 0, "explanation": "A buyer with a backup can push each supplier harder."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why did NASA fund a second Moon lander?", "options": ["For redundancy and competition", "SpaceX's design failed its review", "Congress banned single bids"], "correctIndex": 0, "explanation": "NASA said it wanted two providers for redundancy and competition on long-term Moon missions."}, {"id": "lens-curiosity", "kind": "info", "title": "Two ways to the Moon", "body": "NASA is paying SpaceX and Blue Origin for different landers so its Moon program never depends on one.", "eyebrow": "Why it matters", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"id": "rule", "kind": "microInsight", "text": "In space exploration, paying for a second supplier buys the buyer bargaining power.", "eyebrow": "The rule", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins NASA's second lander"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "NASA paid Blue Origin $3.4 billion in 2023 for a second Moon lander after SpaceX's 2021 win. Two suppliers give NASA redundancy and competition.", "sectionKey": "players"}]}$ml$::jsonb),
($ml$6d65160c-63ac-5d92-a8e1-7af810ea94b8$ml$::uuid, $ml$spacetech$ml$, $ml$NASA's slice of the budget$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-22$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d22-career", "title": "NASA's slice of the budget", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "The Apollo-era money is gone.", "eyebrow": "Day 22 · The numbers", "headline": "In 1966, NASA got 4.41% of the federal budget. By 2019, it got 0.49%.", "fullText": "At the height of Apollo, about one federal dollar in 23 went to NASA. In fiscal 2019 its $21.5 billion budget was less than half a cent of each federal dollar. Congress passed $24.4 billion for fiscal 2026.", "sources": [{"url": "https://www.statista.com/chart/amp/17504/nasas-budget-share-of-the-us-federal-budget", "label": "Statista, NASA's share of the federal budget"}, {"url": "https://space.com/space-exploration/in-rejection-of-trumps-deep-cuts-congress-passes-usd24-4-billion-budget-for-nasa", "label": "Space.com, NASA fiscal 2026 budget"}]}, {"kind": "microInsight", "id": "share", "eyebrow": "The metric", "text": "Budget share shows priority better than dollar totals.", "highlight": "NASA's share of federal spending shrank about ninefold from 1966 to 2019.", "sources": [{"url": "https://www.statista.com/chart/amp/17504/nasas-budget-share-of-the-us-federal-budget", "label": "Statista, NASA's share of the federal budget"}]}, {"kind": "microInsight", "id": "peak", "eyebrow": "The peak", "text": "The peak came with one national goal: landing on the Moon.", "highlight": "The share topped out in 1966, three years before Apollo 11.", "sources": [{"url": "https://www.statista.com/chart/amp/17504/nasas-budget-share-of-the-us-federal-budget", "label": "Statista, NASA's share of the federal budget"}]}, {"kind": "info", "id": "read", "eyebrow": "Read it right", "title": "Read budgets as shares", "body": "A rising dollar total can still be a falling priority. Compare a budget with total federal spending.", "sources": [{"url": "https://www.statista.com/chart/amp/17504/nasas-budget-share-of-the-us-federal-budget", "label": "Statista, NASA's share of the federal budget"}]}, {"kind": "numberSense", "id": "ns-ratio", "prompt": "NASA got 4.41% of the federal budget in 1966 and 0.49% in 2019. About how many times smaller was the 2019 share?", "min": 1, "max": 20, "value": 9, "unit": "x", "explanation": "4.41 divided by 0.49 is 9."}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["NASA's share of the federal budget peaked in 1966.", "NASA got its fiscal 2019 budget of $21.5 billion.", "NASA got about 4% of federal spending in 2019."], "fakeIndex": 2, "explanation": "In 2019 it was 0.49%, less than half a percent."}, {"id": "lens-career", "kind": "info", "title": "Quote the share, not just the total", "body": "NASA gets about half a percent of federal spending. Knowing that frames any talk about its programs.", "eyebrow": "For your interview", "sources": [{"url": "https://www.statista.com/chart/amp/17504/nasas-budget-share-of-the-us-federal-budget", "label": "Statista, NASA's share of the federal budget"}]}, {"id": "rule", "kind": "microInsight", "text": "In government space, a budget's share of spending shows its real priority.", "eyebrow": "The rule", "sources": [{"url": "https://www.statista.com/chart/amp/17504/nasas-budget-share-of-the-us-federal-budget", "label": "Statista, NASA's share of the federal budget"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "NASA got 4.41% of the federal budget in 1966 and 0.49% in 2019. Its share, not its dollar total, shows how much priority space gets.", "sectionKey": "numbers"}]}$ml$::jsonb),
