rum", "text": "The FCC licenses the radio signals a satellite uses.", "highlight": "It also sets rules like the five-year deorbit limit.", "sources": [{"url": "https://www.satellitetoday.com/government-military/2022/09/30/fcc-adopts-5-year-rule-for-deorbiting-satellites/", "label": "Via Satellite, FCC five-year deorbit rule"}]}, {"kind": "info", "id": "imaging", "eyebrow": "License 3 · Imaging", "title": "Imaging needs a third license", "body": "Private operators of remote sensing satellites are licensed by Commerce's Office of Space Commerce.", "keyTerms": [{"term": "Remote sensing", "definition": "Observing Earth from space, for example with cameras or radar."}], "sources": [{"url": "https://space.commerce.gov/regulations/commercial-remote-sensing-regulatory-affairs/", "label": "Office of Space Commerce, remote sensing licensing"}]}, {"kind": "sortSignal", "id": "sort", "prompt": "Which agency licenses it?", "buckets": ["FAA", "FCC", "Commerce"], "items": [{"text": "A rocket launch", "bucket": 0}, {"text": "A capsule's reentry", "bucket": 0}, {"text": "A satellite's radio signals", "bucket": 1}, {"text": "A private imaging satellite", "bucket": 2}], "explanation": "FAA for launch and reentry, FCC for spectrum, Commerce for private remote sensing."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why does a private space mission need government approval at all?", "options": ["Governments own every launch site in the country", "Countries answer for their companies in space", "The United Nations owns outer space"], "correctIndex": 1, "explanation": "Under the Outer Space Treaty, countries are responsible for national activities in space, including private ones."}, {"id": "lens-invest", "kind": "info", "title": "Licenses are a timeline risk", "body": "A satellite cannot earn money until its licenses are in place. Approval timing belongs in any plan.", "eyebrow": "For investors", "sources": [{"url": "https://www.satellitetoday.com/government-military/2022/09/30/fcc-adopts-5-year-rule-for-deorbiting-satellites/", "label": "Via Satellite, FCC five-year deorbit rule"}, {"url": "https://space.commerce.gov/regulations/commercial-remote-sensing-regulatory-affairs/", "label": "Office of Space Commerce, remote sensing licensing"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, you fly on your country's permission.", "eyebrow": "The rule", "sources": [{"url": "https://www.unoosa.org/documents/pdf/spacelaw/activities/2020/SLC2020Presentations/SLC2020PDFPresentations/A._Newman_-_8_Dec_2020_-_Fundamentals_of_Space_Law_.pdf", "label": "UNOOSA, fundamentals of space law"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "US missions can need an FAA launch license, an FCC spectrum license and, for imaging, a Commerce license. Countries answer for their companies under the 1967 treaty.", "sectionKey": "watchlist"}]}$ml$::jsonb),
