ap"}]}$ml$::jsonb),
($ml$91862eec-f7b5-503c-a947-85b9dc21c811$ml$::uuid, $ml$spacetech$ml$, $ml$Who pays if a rocket hits a house$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-26$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:curiosity$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d26-curiosity", "title": "Who pays if a rocket hits a house", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "First the insurer, then the government.", "eyebrow": "Day 26 · The money", "headline": "US launch companies must insure against damage to the public, on average about $99 million per launch.", "fullText": "The FAA works out each launch's maximum probable loss and requires insurance for that amount. Above it, the federal government may cover claims up to an extra $1.5 billion in 1988 dollars, about $2.7 billion by 2012, if Congress approves the money. That backstop has never been paid.", "sources": [{"url": "https://www.gao.gov/products/GAO-12-899", "label": "GAO, commercial space launch insurance and indemnification"}]}, {"kind": "microInsight", "id": "mpl", "eyebrow": "Layer 1", "text": "Maximum probable loss is the FAA's estimate of the worst likely damage to others.", "highlight": "The launch company must insure up to that amount.", "keyTerms": [{"term": "Maximum probable loss", "definition": "The FAA estimate of likely damage to others from a launch, which sets the insurance required."}], "sources": [{"url": "https://www.gao.gov/products/GAO-12-899", "label": "GAO, commercial space launch insurance and indemnification"}]}, {"kind": "microInsight", "id": "backstop", "eyebrow": "Layer 2", "text": "Above the insurance, taxpayers stand behind the launch.", "highlight": "Up to about $2.7 billion more, if Congress approves it.", "sources": [{"url": "https://www.gao.gov/products/GAO-12-899", "label": "GAO, commercial space launch insurance and indemnification"}]}, {"kind": "info", "id": "method", "eyebrow": "The weak spot", "title": "The method was showing its age", "body": "GAO found the FAA's method dated from 1988 and used a $3 million cost per casualty from 2002 data.", "bullets": ["A later review suggested $5 to 6 million per casualty."], "sources": [{"url": "https://www.gao.gov/products/GAO-12-899", "label": "GAO, commercial space launch insurance and indemnification"}]}, {"kind": "numberSense", "id": "ns-mpl", "prompt": "On average, how much third-party insurance did the FAA require per launch, in millions of dollars?", "min": 0, "max": 500, "value": 99, "unit": "M", "explanation": "About $99 million, set by each launch's maximum probable loss."}, {"kind": "faceOff", "id": "face", "prompt": "A launch damages someone's property. Who pays first?", "left": {"name": "The US government", "note": "Covers claims above the insurance"}, "right": {"name": "The launch company's insurer", "note": "Covers up to the maximum probable loss"}, "correctIndex": 1, "explanation": "Insurance pays first, up to the maximum probable loss. The government backstop sits above it."}, {"id": "lens-curiosity", "kind": "info", "title": "Never tested", "body": "The government backstop for launch accidents dates from 1988 and has never had to pay a claim.", "eyebrow": "Why it matters", "sources": [{"url": "https://www.gao.gov/products/GAO-12-899", "label": "GAO, commercial space launch insurance and indemnification"}]}, {"id": "rule", "kind": "microInsight", "text": "In launch, the public is protected by insurance first and taxpayers second.", "eyebrow": "The rule", "sources": [{"url": "https://www.gao.gov/products/GAO-12-899", "label": "GAO, commercial space launch insurance and indemnification"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "The FAA sets required third-party insurance from each launch's maximum probable loss, about $99 million on average. Above that, the government may cover up to about $2.7 billion.", "sectionKey": "chain"}]}$ml$::jsonb),
($ml$ae464271-7f3d-5332-903f-4ab4ef37b5a6$ml$::uuid, $ml$spacetech$ml$, $ml$When a satellite falls, a country pays$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-27$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d27-career", "title": "When a satellite falls, a country pays", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A Soviet satellite came down over Canada.", "eyebrow": "Day 27 · The power", "headline": "In January 1978, the Soviet satellite Cosmos 954 broke up over Canada. The USSR later paid C$3 million.", "fullText": "Under the Outer Space Treaty, a country that launches or procures a launch is internationally liable for damage its space objects cause on Earth, in the air or in space. The settlement with Canada was signed in Moscow in 1981. Because countries carry this liability, they keep tight control over who launches.", "sources": [{"url": "https://www.unoosa.org/oosa/en/ourwork/spacelaw/nationalspacelaw/bi-multi-lateral-agreements/can_ussr_001.html", "label": "UNOOSA, Canada-USSR Cosmos 954 settlement"}, {"url": "https://www.unoosa.org/documents/pdf/spacelaw/activities/2020/SLC2020Presentations/SLC2020PDFPresentations/A._Newman_-_8_Dec_2020_-_Fundamentals_of_Space_Law_.pdf", "label": "UNOOSA, fundamentals of space law"}]}, {"kind": "microInsight", "id": "who", "eyebrow": "Who is liable", "text": "Liability follows the launching country, not just the company.", "highlight": "It includes the country whose territory the launch leaves from.", "sources": [{"url": "https://www.unoosa.org/documents/pdf/spacelaw/activities/2020/SLC2020Presentations/SLC2020PDFPresentations/A._Newman_-_8_Dec_2020_-_Fundamentals_of_Space_Law_.pdf", "label": "UNOOSA, fundamentals of space law"}]}, {"kind": "microInsight", "id": "veto", "eyebrow": "Why it matters", "text": "That liability is why governments hold the power to say no.", "highlight": "If they answer for the damage, they decide who flies.", "sources": [{"url": "https://www.unoosa.org/documents/pdf/spacelaw/activities/2020/SLC2020Presentations/SLC2020PDFPresentations/A._Newman_-_8_Dec_2020_-_Fundamentals_of_Space_Law_.pdf", "label": "UNOOSA, fundamentals of space law"}]}, {"kind": "info", "id": "settlement", "eyebrow": "The outcome", "title": "Canada accepted a full settlement", "body": "The 1981 protocol settled all claims from the breakup for C$3 million.", "sources": [{"url": "https://www.unoosa.org/oosa/en/ourwork/spacelaw/nationalspacelaw/bi-multi-lateral-agreements/can_ussr_001.html", "label": "UNOOSA, Canada-USSR Cosmos 954 settlement"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "Who was liable for the damage from Cosmos 954?", "options": ["The satellite's private builder", "The United Nations space office", "The USSR, as the launching state"], "correctIndex": 2, "explanation": "The treaty makes the launching country liable. The USSR paid Canada C$3 million."}, {"kind": "theCall", "id": "call", "situation": "A foreign startup wants to launch from your country's spaceport.", "prompt": "As the regulator, what do you require?", "options": ["Nothing, since its home country is liable", "Proof of safety and insurance first", "A ban on all foreign payloads"], "consequences": ["The country of the launch site is liable too.", "You carry the liability, so you check the risk.", "A ban gives up the business entirely."], "correctIndex": 1, "explanation": "Launches from your territory make your country liable, so you license them carefully."}, {"id": "lens-career", "kind": "info", "title": "Know who carries liability", "body": "Under the treaty, the launching country is liable for damage. That is why regulators move carefully.", "eyebrow": "For your interview", "sources": [{"url": "https://www.unoosa.org/documents/pdf/spacelaw/activities/2020/SLC2020Presentations/SLC2020PDFPresentations/A._Newman_-_8_Dec_2020_-_Fundamentals_of_Space_Law_.pdf", "label": "UNOOSA, fundamentals of space law"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, whoever carries the liability holds the power to say no.", "eyebrow": "The rule", "sources": [{"url": "https://www.unoosa.org/documents/pdf/spacelaw/activities/2020/SLC2020Presentations/SLC2020PDFPresentations/A._Newman_-_8_Dec_2020_-_Fundamentals_of_Space_Law_.pdf", "label": "UNOOSA, fundamentals of space law"}, {"url": "https://www.unoosa.org/oosa/en/ourwork/spacelaw/nationalspacelaw/bi-multi-lateral-agreements/can_ussr_001.html", "label": "UNOOSA, Canada-USSR Cosmos 954 settlement"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Countries are liable for damage from what they launch, as the Soviet Union was when Cosmos 954 fell on Canada. That liability is why governments control who flies.", "sectionKey": "questions"}]}$ml$::jsonb),
