($ml$9a9eafcf-3d41-5a39-a208-cb93b3c30e50$ml$::uuid, $ml$spacetech$ml$, $ml$The satellites launched without permission$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-29$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d29-career", "title": "The satellites launched without permission", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "The FCC said no. They launched anyway.", "eyebrow": "Day 29 · The rule", "headline": "In January 2018, Swarm Technologies launched four tiny satellites the FCC had refused to approve.", "fullText": "The SpaceBEEs, about a quarter the size of a standard cubesat, flew on India's PSLV. The FCC had worried they would be too hard to track. In December 2018, Swarm agreed to pay $900,000 and accept extra oversight, including reporting each launch deal to the FCC.", "sources": [{"url": "https://techcrunch.com/2018/12/20/fcc-fines-swarm-technologies-900k-over-unauthorized-satellite-launch/", "label": "TechCrunch, FCC fines Swarm $900K"}]}, {"kind": "microInsight", "id": "why", "eyebrow": "The concern", "text": "Too small to track was the problem.", "highlight": "Satellites nobody can track raise collision risk for everyone.", "sources": [{"url": "https://techcrunch.com/2018/12/20/fcc-fines-swarm-technologies-900k-over-unauthorized-satellite-launch/", "label": "TechCrunch, FCC fines Swarm $900K"}]}, {"kind": "microInsight", "id": "penalty", "eyebrow": "The penalty", "text": "Swarm paid $900,000 and came under closer supervision.", "highlight": "It must report each launch deal within five days of signing.", "sources": [{"url": "https://techcrunch.com/2018/12/20/fcc-fines-swarm-technologies-900k-over-unauthorized-satellite-launch/", "label": "TechCrunch, FCC fines Swarm $900K"}]}, {"kind": "info", "id": "abroad", "eyebrow": "The lesson", "title": "The rule follows you abroad", "body": "Swarm launched on an Indian rocket, but as a US company it still answered to the FCC.", "sources": [{"url": "https://techcrunch.com/2018/12/20/fcc-fines-swarm-technologies-900k-over-unauthorized-satellite-launch/", "label": "TechCrunch, FCC fines Swarm $900K"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why had the FCC refused to approve the SpaceBEEs?", "options": ["They used banned radio frequencies", "They had no insurance for the launch", "They were too small to track reliably"], "correctIndex": 2, "explanation": "At about a quarter of a standard cubesat, the FCC judged them too hard to track."}, {"kind": "theCall", "id": "call", "situation": "Your satellite is ready, but your FCC license is still pending. A cheap launch leaves next month.", "prompt": "What do you do?", "options": ["Fly anyway and fix the license later", "Wait for the license or rebook the launch", "Launch abroad to get around the FCC"], "consequences": ["Swarm did that and paid $900,000.", "A later launch costs less than a fine and lost trust.", "Swarm launched from India and still answered to the FCC."], "correctIndex": 1, "explanation": "Operating without a license risks fines and oversight that cost more than waiting."}, {"id": "lens-career", "kind": "info", "title": "Compliance is part of the job", "body": "Swarm paid $900,000 for launching without approval. Regulatory work is core to any satellite program.", "eyebrow": "For your interview", "sources": [{"url": "https://techcrunch.com/2018/12/20/fcc-fines-swarm-technologies-900k-over-unauthorized-satellite-launch/", "label": "TechCrunch, FCC fines Swarm $900K"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, launching without a license costs more than waiting for one.", "eyebrow": "The rule", "sources": [{"url": "https://techcrunch.com/2018/12/20/fcc-fines-swarm-technologies-900k-over-unauthorized-satellite-launch/", "label": "TechCrunch, FCC fines Swarm $900K"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Swarm launched four SpaceBEEs in 2018 after the FCC refused, and paid $900,000. Satellites need their license before they fly, even on a foreign rocket.", "sectionKey": "risk"}]}$ml$::jsonb),
