($ml$9797428d-68bb-5a3c-9632-1f966fd6706a$ml$::uuid, $ml$spacetech$ml$, $ml$327,320 satellites on paper$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-30$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:curiosity$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "spacetech-d30-curiosity", "title": "327,320 satellites on paper", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Filing is easy; flying is not.", "eyebrow": "Day 30 · Where it breaks", "headline": "In September 2021, Rwanda filed at the ITU for a constellation of 327,320 satellites.", "fullText": "The filing, called CINNAMON-937, spread the satellites across 27 orbital shells. It was not clear who would build them. Filings like this reserve frequencies on paper long before anything flies, which is why the ITU added deployment milestones in 2019.", "sources": [{"url": "https://spaceinafrica.com/2021/10/14/rwanda-has-submitted-itu-filing-for-27-orbital-shells-of-327320-satellites/", "label": "Space in Africa, Rwanda's ITU filing"}, {"url": "https://itu.int/en/mediacentre/backgrounders/Pages/Non-geostationary-satellite-systems.aspx", "label": "ITU, non-geostationary satellite systems"}]}, {"kind": "microInsight", "id": "scale", "eyebrow": "The scale", "text": "The filing dwarfs anything in orbit.", "highlight": "Starlink had about 9,400 active satellites in early 2026.", "sources": [{"url": "https://spaceinafrica.com/2021/10/14/rwanda-has-submitted-itu-filing-for-27-orbital-shells-of-327320-satellites/", "label": "Space in Africa, Rwanda's ITU filing"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"kind": "microInsight", "id": "blur", "eyebrow": "The problem", "text": "Paper filings blur the picture of what will really fly.", "highlight": "The ITU's milestones aim to keep its register close to reality.", "sources": [{"url": "https://itu.int/en/mediacentre/backgrounders/Pages/Non-geostationary-satellite-systems.aspx", "label": "ITU, non-geostationary satellite systems"}]}, {"kind": "info", "id": "gap", "eyebrow": "The gap", "title": "Telling real from paper", "body": "Regulators, investors and operators all need better ways to judge which filings will actually launch.", "bullets": ["A subset, CINNAMON-217, alone covered 52,080 satellites."], "sources": [{"url": "https://spaceinafrica.com/2021/10/14/rwanda-has-submitted-itu-filing-for-27-orbital-shells-of-327320-satellites/", "label": "Space in Africa, Rwanda's ITU filing"}, {"url": "https://itu.int/en/mediacentre/backgrounders/Pages/Non-geostationary-satellite-systems.aspx", "label": "ITU, non-geostationary satellite systems"}]}, {"kind": "numberSense", "id": "ns-ratio", "prompt": "Rwanda's filing covered 327,320 satellites; Starlink had about 9,400. Roughly how many times larger was the filing?", "min": 0, "max": 100, "value": 35, "unit": "x", "explanation": "About 35 times Starlink's active fleet."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why did the ITU add deployment milestones in 2019?", "options": ["To keep filings close to what actually flies", "To raise more money from ITU filing fees", "To ban any constellation over 1,000 satellites"], "correctIndex": 0, "explanation": "The milestones aim to make the register reflect real deployment and to prevent spectrum warehousing."}, {"id": "lens-curiosity", "kind": "info", "title": "More satellites on paper than in orbit", "body": "One 2021 filing listed 327,320 satellites, about 35 times Starlink's active fleet in 2026.", "eyebrow": "Why it matters", "sources": [{"url": "https://spaceinafrica.com/2021/10/14/rwanda-has-submitted-itu-filing-for-27-orbital-shells-of-327320-satellites/", "label": "Space in Africa, Rwanda's ITU filing"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, {"id": "rule", "kind": "microInsight", "text": "In space, a filing reserves a claim, but only launches make it real.", "eyebrow": "The rule", "sources": [{"url": "https://itu.int/en/mediacentre/backgrounders/Pages/Non-geostationary-satellite-systems.aspx", "label": "ITU, non-geostationary satellite systems"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Rwanda filed for 327,320 satellites in 2021, about 35 times Starlink's fleet. Paper filings are why the ITU now requires deployment milestones.", "sectionKey": "frontier"}]}$ml$::jsonb)
INSERT INTO slides (id, stack_id, slide_number, title, body, sources) VALUES
($ml$3e1e0d33-0f08-5872-aa24-c6bb5f005b2d$ml$::uuid, $ml$daa7d015-941e-547b-bf11-7f5e705bfed0$ml$::uuid, 1, $ml$Day 6 · Where it breaks$ml$, $ml$From July 2023 to July 2024, Europe had no rocket of its own for big missions. Ariane 5 flew for the 117th and last time on July 5, 2023. Russia had already pulled its Soyuz rockets from Europe's spaceport over sanctions after the invasion of Ukraine, and the new Vega-C failed on its first commercial flight. With Ariane 6 four years late, ESA launched its Euclid space telescope on a SpaceX Falcon 9.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]$ml$::jsonb),
($ml$7df05a0e-b6f3-5594-b7b0-c11f494e9e72$ml$::uuid, $ml$daa7d015-941e-547b-bf11-7f5e705bfed0$ml$::uuid, 2, $ml$The squeeze$ml$, $ml$Europe lost three rockets at once: Ariane 5 retired, Soyuz left and Vega-C failed. Launches from its Kourou spaceport fell from 15 in 2021 to six in 2022.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$7efd500b-13d2-5f1e-b95c-a60f99c34401$ml$::uuid, $ml$daa7d015-941e-547b-bf11-7f5e705bfed0$ml$::uuid, 3, $ml$The workaround$ml$, $ml$ESA put its Euclid telescope on a SpaceX Falcon 9. With no option of its own, Europe paid a competitor to fly its science.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$b6b3c593-6009-54ce-ad37-991329fcf54c$ml$::uuid, $ml$daa7d015-941e-547b-bf11-7f5e705bfed0$ml$::uuid, 4, $ml$Ariane 6 flew in July 2024$ml$, $ml$Its first launch, on July 9, 2024, restored Europe's own access to space. The original target had been 2020. Six Ariane 6 launches were planned for 2025 and eight for 2026.$ml$, $ml$[{"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}, {"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$e608c554-7a2c-5d56-ab3d-bb2d924cdfdd$ml$::uuid, $ml$daa7d015-941e-547b-bf11-7f5e705bfed0$ml$::uuid, 5, $ml$Ask about the backup ride$ml$, $ml$Ask which rocket a mission is booked on and what happens if it slips. Europe's 2023 gap shows why it matters.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$94726cb3-5c7f-59dc-8618-4776bb97a205$ml$::uuid, $ml$daa7d015-941e-547b-bf11-7f5e705bfed0$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, depending on one launcher is a single point of failure.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]$ml$::jsonb),
($ml$f95205e6-bd5d-55e5-9184-7372d54f01d7$ml$::uuid, $ml$8d80b9ac-0eea-5d27-b4e8-e06a3a7e73e1$ml$::uuid, 1, $ml$Day 6 · Where it breaks$ml$, $ml$From July 2023 to July 2024, Europe had no rocket of its own for big missions. Ariane 5 flew for the 117th and last time on July 5, 2023. Russia had already pulled its Soyuz rockets from Europe's spaceport over sanctions after the invasion of Ukraine, and the new Vega-C failed on its first commercial flight. With Ariane 6 four years late, ESA launched its Euclid space telescope on a SpaceX Falcon 9.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]$ml$::jsonb),
($ml$1112700e-4132-562a-a59d-82c112e237f9$ml$::uuid, $ml$8d80b9ac-0eea-5d27-b4e8-e06a3a7e73e1$ml$::uuid, 2, $ml$The squeeze$ml$, $ml$Europe lost three rockets at once: Ariane 5 retired, Soyuz left and Vega-C failed. Launches from its Kourou spaceport fell from 15 in 2021 to six in 2022.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$2458a10c-fa57-59af-b928-a7ae46c06960$ml$::uuid, $ml$8d80b9ac-0eea-5d27-b4e8-e06a3a7e73e1$ml$::uuid, 3, $ml$The workaround$ml$, $ml$ESA put its Euclid telescope on a SpaceX Falcon 9. With no option of its own, Europe paid a competitor to fly its science.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$6a82268b-ac2e-5730-8ec8-5aa9e0b1b0cd$ml$::uuid, $ml$8d80b9ac-0eea-5d27-b4e8-e06a3a7e73e1$ml$::uuid, 4, $ml$Ariane 6 flew in July 2024$ml$, $ml$Its first launch, on July 9, 2024, restored Europe's own access to space. The original target had been 2020. Six Ariane 6 launches were planned for 2025 and eight for 2026.$ml$, $ml$[{"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}, {"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$7fdfe85d-03e2-5ed6-9477-6134f17dcbb1$ml$::uuid, $ml$8d80b9ac-0eea-5d27-b4e8-e06a3a7e73e1$ml$::uuid, 5, $ml$Launch gaps move contracts$ml$, $ml$When Europe lost its rockets, missions moved to SpaceX. Gaps like that shift revenue to whoever can fly.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$eec03b51-05f1-59a0-ad4e-da223c2eab1d$ml$::uuid, $ml$8d80b9ac-0eea-5d27-b4e8-e06a3a7e73e1$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, depending on one launcher is a single point of failure.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]$ml$::jsonb),
($ml$3ce58bb5-716e-57f4-b619-2d539ad45c15$ml$::uuid, $ml$5c2043b4-1298-5139-8669-8721da957115$ml$::uuid, 1, $ml$Day 6 · Where it breaks$ml$, $ml$From July 2023 to July 2024, Europe had no rocket of its own for big missions. Ariane 5 flew for the 117th and last time on July 5, 2023. Russia had already pulled its Soyuz rockets from Europe's spaceport over sanctions after the invasion of Ukraine, and the new Vega-C failed on its first commercial flight. With Ariane 6 four years late, ESA launched its Euclid space telescope on a SpaceX Falcon 9.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]$ml$::jsonb),
($ml$dac6325c-6d0a-5b4d-a6d2-3d8a4a9d59df$ml$::uuid, $ml$5c2043b4-1298-5139-8669-8721da957115$ml$::uuid, 2, $ml$The squeeze$ml$, $ml$Europe lost three rockets at once: Ariane 5 retired, Soyuz left and Vega-C failed. Launches from its Kourou spaceport fell from 15 in 2021 to six in 2022.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$06710afb-af85-53db-8f79-ab50b05334e5$ml$::uuid, $ml$5c2043b4-1298-5139-8669-8721da957115$ml$::uuid, 3, $ml$The workaround$ml$, $ml$ESA put its Euclid telescope on a SpaceX Falcon 9. With no option of its own, Europe paid a competitor to fly its science.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$5da8aaec-6df4-5a25-ab21-d8fd31a6d412$ml$::uuid, $ml$5c2043b4-1298-5139-8669-8721da957115$ml$::uuid, 4, $ml$Ariane 6 flew in July 2024$ml$, $ml$Its first launch, on July 9, 2024, restored Europe's own access to space. The original target had been 2020. Six Ariane 6 launches were planned for 2025 and eight for 2026.$ml$, $ml$[{"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}, {"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$d7062b18-2b7f-5eca-9b58-aca12a5564d3$ml$::uuid, $ml$5c2043b4-1298-5139-8669-8721da957115$ml$::uuid, 5, $ml$Independence has buyers$ml$, $ml$Europe paid a rival to fly its own science. Customers who need a second way to orbit will pay for one.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]$ml$::jsonb),
($ml$fddab5c4-f0dc-5094-add2-bdf08e9e3959$ml$::uuid, $ml$5c2043b4-1298-5139-8669-8721da957115$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, depending on one launcher is a single point of failure.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]$ml$::jsonb),
($ml$42221804-5bba-5993-bebe-d1444004f753$ml$::uuid, $ml$a4469efe-4ea5-57ef-afb6-081d2bfa707a$ml$::uuid, 1, $ml$Day 6 · Where it breaks$ml$, $ml$From July 2023 to July 2024, Europe had no rocket of its own for big missions. Ariane 5 flew for the 117th and last time on July 5, 2023. Russia had already pulled its Soyuz rockets from Europe's spaceport over sanctions after the invasion of Ukraine, and the new Vega-C failed on its first commercial flight. With Ariane 6 four years late, ESA launched its Euclid space telescope on a SpaceX Falcon 9.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]$ml$::jsonb),
($ml$9fd5e5c6-effd-5177-9820-81e07fbcf8e0$ml$::uuid, $ml$a4469efe-4ea5-57ef-afb6-081d2bfa707a$ml$::uuid, 2, $ml$The squeeze$ml$, $ml$Europe lost three rockets at once: Ariane 5 retired, Soyuz left and Vega-C failed. Launches from its Kourou spaceport fell from 15 in 2021 to six in 2022.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$f980a53e-ffc6-53e1-80e2-51104c4d0bfb$ml$::uuid, $ml$a4469efe-4ea5-57ef-afb6-081d2bfa707a$ml$::uuid, 3, $ml$The workaround$ml$, $ml$ESA put its Euclid telescope on a SpaceX Falcon 9. With no option of its own, Europe paid a competitor to fly its science.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$ada56078-8e1d-5f3d-9422-5b2f15a9f87e$ml$::uuid, $ml$a4469efe-4ea5-57ef-afb6-081d2bfa707a$ml$::uuid, 4, $ml$Ariane 6 flew in July 2024$ml$, $ml$Its first launch, on July 9, 2024, restored Europe's own access to space. The original target had been 2020. Six Ariane 6 launches were planned for 2025 and eight for 2026.$ml$, $ml$[{"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}, {"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$031454b0-473d-5b9a-a322-284e3f1c33db$ml$::uuid, $ml$a4469efe-4ea5-57ef-afb6-081d2bfa707a$ml$::uuid, 5, $ml$Even agencies need a ride$ml$, $ml$Europe's space agency had to launch its telescope on an American rocket. Access to orbit is not guaranteed.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]$ml$::jsonb),
($ml$59709696-0640-57aa-b0f7-4a4a88395bd9$ml$::uuid, $ml$a4469efe-4ea5-57ef-afb6-081d2bfa707a$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, depending on one launcher is a single point of failure.$ml$, $ml$[{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}]$ml$::jsonb),
($ml$d0e8bbf2-6de9-5c18-b1f0-693a688b5597$ml$::uuid, $ml$17478646-1bdd-59ea-b928-d029ba73276d$ml$::uuid, 1, $ml$Day 7 · Orbits$ml$, $ml$A satellite 35,786 km up circles Earth exactly once a day. Low Earth orbit runs from about 160 to 2,000 km, where a lap takes 90 minutes to 2 hours. GPS satellites sit in medium orbit near 20,000 km and circle about twice a day. At 35,786 km, a lap matches Earth's spin, so a geostationary satellite seems to hang over one spot.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$a8ac5455-5660-547f-90ed-c4768ba771f0$ml$::uuid, $ml$17478646-1bdd-59ea-b928-d029ba73276d$ml$::uuid, 2, $ml$Low Earth orbit$ml$, $ml$Low orbit is close and fast: a lap takes 90 minutes to 2 hours. Iridium's 66 phone satellites fly at about 780 km.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$02156efa-5270-5d5d-8404-89114e0bf044$ml$::uuid, $ml$17478646-1bdd-59ea-b928-d029ba73276d$ml$::uuid, 3, $ml$Medium Earth orbit$ml$, $ml$Medium orbit is home to navigation: GPS flies at about 20,000 km. A lap there takes about 12 hours.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$d540b5ac-164a-5804-a926-c73cb31e2631$ml$::uuid, $ml$17478646-1bdd-59ea-b928-d029ba73276d$ml$::uuid, 4, $ml$Geostationary satellites hover over one spot$ml$, $ml$At 35,786 km a lap takes one day, so a dish on the ground can point at one fixed place. One geostationary satellite sees about a third of the planet.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$552ceb80-4b21-53d1-b153-c6d68502c383$ml$::uuid, $ml$17478646-1bdd-59ea-b928-d029ba73276d$ml$::uuid, 5, $ml$Know the orbit before the company$ml$, $ml$Say which orbit a company works in. Low, medium and geostationary mean different products, customers and risks.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$f850cfd3-1e99-5134-b0e4-601ee31452cd$ml$::uuid, $ml$17478646-1bdd-59ea-b928-d029ba73276d$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, the orbit you choose decides what you can sell.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$ef3f0c72-3be8-5c3f-b76d-877f5f445a8a$ml$::uuid, $ml$d6677782-d752-5078-8d13-bc87b7251eec$ml$::uuid, 1, $ml$Day 7 · Orbits$ml$, $ml$A satellite 35,786 km up circles Earth exactly once a day. Low Earth orbit runs from about 160 to 2,000 km, where a lap takes 90 minutes to 2 hours. GPS satellites sit in medium orbit near 20,000 km and circle about twice a day. At 35,786 km, a lap matches Earth's spin, so a geostationary satellite seems to hang over one spot.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$05ad1a54-dadf-5c76-b77f-b67425b71517$ml$::uuid, $ml$d6677782-d752-5078-8d13-bc87b7251eec$ml$::uuid, 2, $ml$Low Earth orbit$ml$, $ml$Low orbit is close and fast: a lap takes 90 minutes to 2 hours. Iridium's 66 phone satellites fly at about 780 km.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$42cfadc8-31fa-5bf5-a2b5-746eb50fc3f3$ml$::uuid, $ml$d6677782-d752-5078-8d13-bc87b7251eec$ml$::uuid, 3, $ml$Medium Earth orbit$ml$, $ml$Medium orbit is home to navigation: GPS flies at about 20,000 km. A lap there takes about 12 hours.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$397931ca-8830-5f4c-b3b3-458b9935b69a$ml$::uuid, $ml$d6677782-d752-5078-8d13-bc87b7251eec$ml$::uuid, 4, $ml$Geostationary satellites hover over one spot$ml$, $ml$At 35,786 km a lap takes one day, so a dish on the ground can point at one fixed place. One geostationary satellite sees about a third of the planet.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$52f88018-97d0-5ffb-9187-e3b21c897329$ml$::uuid, $ml$d6677782-d752-5078-8d13-bc87b7251eec$ml$::uuid, 5, $ml$Orbit shapes the business model$ml$, $ml$Geostationary operators sell from a few big satellites, low-orbit ones from many small satellites. The capital needs differ.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$8d88f80f-0649-5dc3-96ca-0166b2309d08$ml$::uuid, $ml$d6677782-d752-5078-8d13-bc87b7251eec$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, the orbit you choose decides what you can sell.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$25f3677e-34fd-5201-92d9-4851b7457c22$ml$::uuid, $ml$d5a57b55-c6d6-57cf-aa1d-d32a986e764e$ml$::uuid, 1, $ml$Day 7 · Orbits$ml$, $ml$A satellite 35,786 km up circles Earth exactly once a day. Low Earth orbit runs from about 160 to 2,000 km, where a lap takes 90 minutes to 2 hours. GPS satellites sit in medium orbit near 20,000 km and circle about twice a day. At 35,786 km, a lap matches Earth's spin, so a geostationary satellite seems to hang over one spot.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$8af83c0f-729d-58a3-b2f4-7814caf9103a$ml$::uuid, $ml$d5a57b55-c6d6-57cf-aa1d-d32a986e764e$ml$::uuid, 2, $ml$Low Earth orbit$ml$, $ml$Low orbit is close and fast: a lap takes 90 minutes to 2 hours. Iridium's 66 phone satellites fly at about 780 km.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$5db9295d-92f5-505c-afe8-08765740401b$ml$::uuid, $ml$d5a57b55-c6d6-57cf-aa1d-d32a986e764e$ml$::uuid, 3, $ml$Medium Earth orbit$ml$, $ml$Medium orbit is home to navigation: GPS flies at about 20,000 km. A lap there takes about 12 hours.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$fe63b9c2-2260-5a8e-b947-9333abf0d033$ml$::uuid, $ml$d5a57b55-c6d6-57cf-aa1d-d32a986e764e$ml$::uuid, 4, $ml$Geostationary satellites hover over one spot$ml$, $ml$At 35,786 km a lap takes one day, so a dish on the ground can point at one fixed place. One geostationary satellite sees about a third of the planet.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$b161260d-5321-52f2-9efc-39a35566b065$ml$::uuid, $ml$d5a57b55-c6d6-57cf-aa1d-d32a986e764e$ml$::uuid, 5, $ml$The job picks the height$ml$, $ml$Phone networks and crew labs fly low, navigation sits in medium orbit, broadcasting lives in geostationary orbit.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$d1333ec2-8c15-527c-bcc2-c7f81b5f1586$ml$::uuid, $ml$d5a57b55-c6d6-57cf-aa1d-d32a986e764e$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, the orbit you choose decides what you can sell.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$bf340a47-a383-5352-94d0-51b8005e0d28$ml$::uuid, $ml$28a8fdd2-08d7-517b-9137-671ddbdc40c3$ml$::uuid, 1, $ml$Day 7 · Orbits$ml$, $ml$A satellite 35,786 km up circles Earth exactly once a day. Low Earth orbit runs from about 160 to 2,000 km, where a lap takes 90 minutes to 2 hours. GPS satellites sit in medium orbit near 20,000 km and circle about twice a day. At 35,786 km, a lap matches Earth's spin, so a geostationary satellite seems to hang over one spot.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$a7a3633a-851d-50fc-ae81-672f4904cee5$ml$::uuid, $ml$28a8fdd2-08d7-517b-9137-671ddbdc40c3$ml$::uuid, 2, $ml$Low Earth orbit$ml$, $ml$Low orbit is close and fast: a lap takes 90 minutes to 2 hours. Iridium's 66 phone satellites fly at about 780 km.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$051a74f6-1d39-550d-aa61-832f97622485$ml$::uuid, $ml$28a8fdd2-08d7-517b-9137-671ddbdc40c3$ml$::uuid, 3, $ml$Medium Earth orbit$ml$, $ml$Medium orbit is home to navigation: GPS flies at about 20,000 km. A lap there takes about 12 hours.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$cdc04a0f-7594-5b4b-abf2-13e869afd350$ml$::uuid, $ml$28a8fdd2-08d7-517b-9137-671ddbdc40c3$ml$::uuid, 4, $ml$Geostationary satellites hover over one spot$ml$, $ml$At 35,786 km a lap takes one day, so a dish on the ground can point at one fixed place. One geostationary satellite sees about a third of the planet.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$8c7b8e52-f282-5458-bbbc-5f38721596ab$ml$::uuid, $ml$28a8fdd2-08d7-517b-9137-671ddbdc40c3$ml$::uuid, 5, $ml$Height sets the clock$ml$, $ml$The higher the orbit, the longer the lap: 90 minutes low, about 12 hours for GPS, a full day at 35,786 km.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$e3319971-e627-5742-9292-4fd570afb6bb$ml$::uuid, $ml$28a8fdd2-08d7-517b-9137-671ddbdc40c3$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, the orbit you choose decides what you can sell.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$ca134bb1-fb45-5b2c-9a7f-412a38dabb39$ml$::uuid, $ml$c651c3e2-ada6-5bab-88e9-540e8ed31976$ml$::uuid, 1, $ml$Day 8 · The money$ml$, $ml$One geostationary satellite sees a third of Earth. Starlink flies about 9,400. A satellite at 35,786 km sees about a third of the planet, so a handful can serve whole continents. A low satellite sees a small patch and races past it in minutes, so a network needs many more to keep a customer connected. Starlink had roughly 9,400 active satellites in early 2026.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]$ml$::jsonb),
($ml$039659b1-8585-5b63-bad5-3817336b006f$ml$::uuid, $ml$c651c3e2-ada6-5bab-88e9-540e8ed31976$ml$::uuid, 2, $ml$The delay$ml$, $ml$The trade is distance for delay. Up to a geostationary satellite and back down is about 71,600 km: a quarter of a second, even at light speed.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$fa7cfbe6-8999-559f-af9b-93f53d062b04$ml$::uuid, $ml$c651c3e2-ada6-5bab-88e9-540e8ed31976$ml$::uuid, 3, $ml$The bill$ml$, $ml$Low orbit cuts the delay but multiplies the hardware bill. Each low satellite only serves customers while it passes over them.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$02b1467e-3a90-58cf-bd5c-24db70141ed6$ml$::uuid, $ml$c651c3e2-ada6-5bab-88e9-540e8ed31976$ml$::uuid, 4, $ml$Two ways to cover the planet$ml$, $ml$Geostationary: a few large satellites far away. Low orbit: many satellites close by, each in view for minutes. Iridium covers the globe with 66 satellites at about 780 km.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$5f8e0c55-b6c8-5a67-9681-5e7b931ca25f$ml$::uuid, $ml$c651c3e2-ada6-5bab-88e9-540e8ed31976$ml$::uuid, 5, $ml$Explain the latency trade$ml$, $ml$Be ready to explain why low orbit means less delay but far more satellites. It is the core trade in satellite internet.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$c99867b9-3e19-5200-ba6c-75f2df9b6704$ml$::uuid, $ml$c651c3e2-ada6-5bab-88e9-540e8ed31976$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, closer satellites are faster, but you need far more of them.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]$ml$::jsonb),
($ml$8f0c3100-c203-529e-acc2-6927784e6504$ml$::uuid, $ml$a0212085-abf4-5e4b-9a31-50ba19dacf00$ml$::uuid, 1, $ml$Day 8 · The money$ml$, $ml$One geostationary satellite sees a third of Earth. Starlink flies about 9,400. A satellite at 35,786 km sees about a third of the planet, so a handful can serve whole continents. A low satellite sees a small patch and races past it in minutes, so a network needs many more to keep a customer connected. Starlink had roughly 9,400 active satellites in early 2026.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]$ml$::jsonb),
($ml$0a7100e3-9c05-5e42-96fb-5d08906c87b5$ml$::uuid, $ml$a0212085-abf4-5e4b-9a31-50ba19dacf00$ml$::uuid, 2, $ml$The delay$ml$, $ml$The trade is distance for delay. Up to a geostationary satellite and back down is about 71,600 km: a quarter of a second, even at light speed.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$21b68b3f-840c-5370-9c31-3246a246fb85$ml$::uuid, $ml$a0212085-abf4-5e4b-9a31-50ba19dacf00$ml$::uuid, 3, $ml$The bill$ml$, $ml$Low orbit cuts the delay but multiplies the hardware bill. Each low satellite only serves customers while it passes over them.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$80f989dd-d628-5f2c-beac-c8a07aed6dc4$ml$::uuid, $ml$a0212085-abf4-5e4b-9a31-50ba19dacf00$ml$::uuid, 4, $ml$Two ways to cover the planet$ml$, $ml$Geostationary: a few large satellites far away. Low orbit: many satellites close by, each in view for minutes. Iridium covers the globe with 66 satellites at about 780 km.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$92a16812-50e8-5779-8e2f-b6ae945496fb$ml$::uuid, $ml$a0212085-abf4-5e4b-9a31-50ba19dacf00$ml$::uuid, 5, $ml$More satellites, more capital$ml$, $ml$A low-orbit network needs thousands of satellites before it can serve everyone. Ask how it pays for them.$ml$, $ml$[{"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]$ml$::jsonb),
($ml$ff534e8d-cf47-5286-bea4-4275906440cf$ml$::uuid, $ml$a0212085-abf4-5e4b-9a31-50ba19dacf00$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, closer satellites are faster, but you need far more of them.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]$ml$::jsonb),
($ml$cc5895a2-be0e-5c25-b043-cbe96b364fc0$ml$::uuid, $ml$440d1c24-e778-53d9-8c1d-938797b19054$ml$::uuid, 1, $ml$Day 8 · The money$ml$, $ml$One geostationary satellite sees a third of Earth. Starlink flies about 9,400. A satellite at 35,786 km sees about a third of the planet, so a handful can serve whole continents. A low satellite sees a small patch and races past it in minutes, so a network needs many more to keep a customer connected. Starlink had roughly 9,400 active satellites in early 2026.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]$ml$::jsonb),
($ml$5a67ccc3-6155-5825-af84-37d8194e5d7d$ml$::uuid, $ml$440d1c24-e778-53d9-8c1d-938797b19054$ml$::uuid, 2, $ml$The delay$ml$, $ml$The trade is distance for delay. Up to a geostationary satellite and back down is about 71,600 km: a quarter of a second, even at light speed.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$f508dbe1-86d6-5ffc-8085-054229edf4e1$ml$::uuid, $ml$440d1c24-e778-53d9-8c1d-938797b19054$ml$::uuid, 3, $ml$The bill$ml$, $ml$Low orbit cuts the delay but multiplies the hardware bill. Each low satellite only serves customers while it passes over them.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$22168b68-da0a-58bb-a271-287969d06bfa$ml$::uuid, $ml$440d1c24-e778-53d9-8c1d-938797b19054$ml$::uuid, 4, $ml$Two ways to cover the planet$ml$, $ml$Geostationary: a few large satellites far away. Low orbit: many satellites close by, each in view for minutes. Iridium covers the globe with 66 satellites at about 780 km.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$6c4419ea-91e4-557d-9d1b-792dbd6e7f59$ml$::uuid, $ml$440d1c24-e778-53d9-8c1d-938797b19054$ml$::uuid, 5, $ml$Find who needs fast links$ml$, $ml$Low delay matters for calls and gaming. Wide, slower coverage from far away still suits TV broadcasting.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$932efdd4-94b4-52fe-a02c-97532f4ed843$ml$::uuid, $ml$440d1c24-e778-53d9-8c1d-938797b19054$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, closer satellites are faster, but you need far more of them.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]$ml$::jsonb),
($ml$afa0e47c-f6aa-534b-a3d1-ace3cc10bdda$ml$::uuid, $ml$d65b560f-469e-5695-abdd-0496e60328ac$ml$::uuid, 1, $ml$Day 8 · The money$ml$, $ml$One geostationary satellite sees a third of Earth. Starlink flies about 9,400. A satellite at 35,786 km sees about a third of the planet, so a handful can serve whole continents. A low satellite sees a small patch and races past it in minutes, so a network needs many more to keep a customer connected. Starlink had roughly 9,400 active satellites in early 2026.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]$ml$::jsonb),
($ml$0b8059c1-ccd0-54a0-bd96-e345c2d25546$ml$::uuid, $ml$d65b560f-469e-5695-abdd-0496e60328ac$ml$::uuid, 2, $ml$The delay$ml$, $ml$The trade is distance for delay. Up to a geostationary satellite and back down is about 71,600 km: a quarter of a second, even at light speed.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$12b62877-86ed-59a9-82e7-ad1112a34378$ml$::uuid, $ml$d65b560f-469e-5695-abdd-0496e60328ac$ml$::uuid, 3, $ml$The bill$ml$, $ml$Low orbit cuts the delay but multiplies the hardware bill. Each low satellite only serves customers while it passes over them.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$9fdffc13-c7dc-5dab-b661-2aae62069b05$ml$::uuid, $ml$d65b560f-469e-5695-abdd-0496e60328ac$ml$::uuid, 4, $ml$Two ways to cover the planet$ml$, $ml$Geostationary: a few large satellites far away. Low orbit: many satellites close by, each in view for minutes. Iridium covers the globe with 66 satellites at about 780 km.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$94ffbed2-ad38-54c4-abde-cfa0900b1e6c$ml$::uuid, $ml$d65b560f-469e-5695-abdd-0496e60328ac$ml$::uuid, 5, $ml$Distance costs time$ml$, $ml$Even at light speed, a trip to 35,786 km and back takes about a quarter of a second.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$06b47c7d-1312-534f-8b6e-2c68ee0c1bab$ml$::uuid, $ml$d65b560f-469e-5695-abdd-0496e60328ac$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, closer satellites are faster, but you need far more of them.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]$ml$::jsonb),
($ml$93d835d9-ee87-5f82-87be-20fe11ad4837$ml$::uuid, $ml$b6e8230d-b715-5ee0-9dde-fb5a52be65e5$ml$::uuid, 1, $ml$Day 9 · The power$ml$, $ml$A 50 kg seat on SpaceX's Transporter costs $350,000 for 2026 flights. SpaceX's Transporter flights carry dozens of small satellites at once to sun-synchronous orbit. The price works out to about $7,000 per kg, up from $5,500 per kg before 2023. In exchange, operators give up control over their orbital destination and their launch schedule.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}, {"url": "https://payloadspace.com/spacex-increases-rideshare-prices", "label": "Payload, SpaceX raises rideshare prices"}]$ml$::jsonb),
($ml$6a5c0a24-4c1b-58a7-81f2-390361ef8afc$ml$::uuid, $ml$b6e8230d-b715-5ee0-9dde-fb5a52be65e5$ml$::uuid, 2, $ml$Who decides$ml$, $ml$The rocket sets the orbit and the date. Rideshare payloads go along. A standard Transporter won't drop you at 37 degrees or 450 km.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$f05a54e1-1ad4-5eb8-b364-9bbef92a67ca$ml$::uuid, $ml$b6e8230d-b715-5ee0-9dde-fb5a52be65e5$ml$::uuid, 3, $ml$Who sets the price$ml$, $ml$The rocket owner sets the price: it rose from $5,500 to $6,500 per kg in 2023. It reached about $7,000 per kg for 2026 flights.$ml$, $ml$[{"url": "https://payloadspace.com/spacex-increases-rideshare-prices", "label": "Payload, SpaceX raises rideshare prices"}, {"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$24cfd724-a4ef-58f0-8460-1cc4b22a3b32$ml$::uuid, $ml$b6e8230d-b715-5ee0-9dde-fb5a52be65e5$ml$::uuid, 4, $ml$Space tugs sell the last mile$ml$, $ml$Orbital transfer vehicles ride up as one payload, then use their own engines to drop satellites where they need to be. D-Orbit has flown 21 of its ION carriers.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$7d8d3854-8b35-5cc4-a49f-2ac3231dcfc9$ml$::uuid, $ml$b6e8230d-b715-5ee0-9dde-fb5a52be65e5$ml$::uuid, 5, $ml$Ask where the ride drops you$ml$, $ml$Ask how a team gets from the rideshare drop-off to its working orbit. It shows you know the real constraint.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$807807ad-17c3-5499-98fc-95b5fcfe6b3e$ml$::uuid, $ml$b6e8230d-b715-5ee0-9dde-fb5a52be65e5$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, whoever owns the ride decides the orbit and the date.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$7094ae0e-7ccb-5f90-9a82-c9fe44df7309$ml$::uuid, $ml$60a410fc-bf99-5eda-8950-343e9766b61a$ml$::uuid, 1, $ml$Day 9 · The power$ml$, $ml$A 50 kg seat on SpaceX's Transporter costs $350,000 for 2026 flights. SpaceX's Transporter flights carry dozens of small satellites at once to sun-synchronous orbit. The price works out to about $7,000 per kg, up from $5,500 per kg before 2023. In exchange, operators give up control over their orbital destination and their launch schedule.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}, {"url": "https://payloadspace.com/spacex-increases-rideshare-prices", "label": "Payload, SpaceX raises rideshare prices"}]$ml$::jsonb),
($ml$ed3c7195-9c91-524a-af86-88f3eb969392$ml$::uuid, $ml$60a410fc-bf99-5eda-8950-343e9766b61a$ml$::uuid, 2, $ml$Who decides$ml$, $ml$The rocket sets the orbit and the date. Rideshare payloads go along. A standard Transporter won't drop you at 37 degrees or 450 km.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
