($ml$40894a91-ba31-5186-9472-4144b5e5f159$ml$::uuid, $ml$60a410fc-bf99-5eda-8950-343e9766b61a$ml$::uuid, 4, $ml$Space tugs sell the last mile$ml$, $ml$Orbital transfer vehicles ride up as one payload, then use their own engines to drop satellites where they need to be. D-Orbit has flown 21 of its ION carriers.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$7a3e0141-f018-5c89-badf-251bd864881c$ml$::uuid, $ml$60a410fc-bf99-5eda-8950-343e9766b61a$ml$::uuid, 5, $ml$Watch who owns the ride$ml$, $ml$Rideshare is cheap, but the rocket owner sets price and schedule. That control shows up in every rider's plan.$ml$, $ml$[{"url": "https://payloadspace.com/spacex-increases-rideshare-prices", "label": "Payload, SpaceX raises rideshare prices"}, {"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
