($ml$11ab4242-d25f-51f1-9125-715451ab474a$ml$::uuid, $ml$31f6eaf6-7000-5f4c-8f3b-24ddecb1c3de$ml$::uuid, 1, $ml$Day 9 · The power$ml$, $ml$A 50 kg seat on SpaceX's Transporter costs $350,000 for 2026 flights. SpaceX's Transporter flights carry dozens of small satellites at once to sun-synchronous orbit. The price works out to about $7,000 per kg, up from $5,500 per kg before 2023. In exchange, operators give up control over their orbital destination and their launch schedule.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}, {"url": "https://payloadspace.com/spacex-increases-rideshare-prices", "label": "Payload, SpaceX raises rideshare prices"}]$ml$::jsonb),
($ml$87e7358c-16fb-5876-8035-f629fd7422f7$ml$::uuid, $ml$31f6eaf6-7000-5f4c-8f3b-24ddecb1c3de$ml$::uuid, 2, $ml$Who decides$ml$, $ml$The rocket sets the orbit and the date. Rideshare payloads go along. A standard Transporter won't drop you at 37 degrees or 450 km.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$5c21f33e-9532-5c4c-adca-41c7dc4a43e0$ml$::uuid, $ml$31f6eaf6-7000-5f4c-8f3b-24ddecb1c3de$ml$::uuid, 3, $ml$Who sets the price$ml$, $ml$The rocket owner sets the price: it rose from $5,500 to $6,500 per kg in 2023. It reached about $7,000 per kg for 2026 flights.$ml$, $ml$[{"url": "https://payloadspace.com/spacex-increases-rideshare-prices", "label": "Payload, SpaceX raises rideshare prices"}, {"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$5e963a39-1e73-53c2-83ac-e458b11d460b$ml$::uuid, $ml$31f6eaf6-7000-5f4c-8f3b-24ddecb1c3de$ml$::uuid, 4, $ml$Space tugs sell the last mile$ml$, $ml$Orbital transfer vehicles ride up as one payload, then use their own engines to drop satellites where they need to be. D-Orbit has flown 21 of its ION carriers.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$f15527dd-1a0e-5261-8042-8db34c228064$ml$::uuid, $ml$31f6eaf6-7000-5f4c-8f3b-24ddecb1c3de$ml$::uuid, 5, $ml$The last mile is a business$ml$, $ml$Rideshare drops everyone in roughly the same orbit. Moving satellites from there is a service people pay for.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$84242a0b-1aa0-5c87-92d2-4b002962639f$ml$::uuid, $ml$31f6eaf6-7000-5f4c-8f3b-24ddecb1c3de$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, whoever owns the ride decides the orbit and the date.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$5c7fd463-f609-5e08-a69c-335dddafd393$ml$::uuid, $ml$2caab2b2-5efa-5beb-97ef-7bd1878265fe$ml$::uuid, 1, $ml$Day 9 · The power$ml$, $ml$A 50 kg seat on SpaceX's Transporter costs $350,000 for 2026 flights. SpaceX's Transporter flights carry dozens of small satellites at once to sun-synchronous orbit. The price works out to about $7,000 per kg, up from $5,500 per kg before 2023. In exchange, operators give up control over their orbital destination and their launch schedule.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}, {"url": "https://payloadspace.com/spacex-increases-rideshare-prices", "label": "Payload, SpaceX raises rideshare prices"}]$ml$::jsonb),
($ml$783e583c-32d2-5c76-888e-90c54d6b4983$ml$::uuid, $ml$2caab2b2-5efa-5beb-97ef-7bd1878265fe$ml$::uuid, 2, $ml$Who decides$ml$, $ml$The rocket sets the orbit and the date. Rideshare payloads go along. A standard Transporter won't drop you at 37 degrees or 450 km.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$229eee15-7d8f-5601-b71a-d258524a69f0$ml$::uuid, $ml$2caab2b2-5efa-5beb-97ef-7bd1878265fe$ml$::uuid, 3, $ml$Who sets the price$ml$, $ml$The rocket owner sets the price: it rose from $5,500 to $6,500 per kg in 2023. It reached about $7,000 per kg for 2026 flights.$ml$, $ml$[{"url": "https://payloadspace.com/spacex-increases-rideshare-prices", "label": "Payload, SpaceX raises rideshare prices"}, {"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$d2d7e12d-1456-5e6a-b645-35347c086a68$ml$::uuid, $ml$2caab2b2-5efa-5beb-97ef-7bd1878265fe$ml$::uuid, 4, $ml$Space tugs sell the last mile$ml$, $ml$Orbital transfer vehicles ride up as one payload, then use their own engines to drop satellites where they need to be. D-Orbit has flown 21 of its ION carriers.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$dfd53eff-6cc1-5f01-8b64-2fdc25bc4347$ml$::uuid, $ml$2caab2b2-5efa-5beb-97ef-7bd1878265fe$ml$::uuid, 5, $ml$Carpooling to orbit$ml$, $ml$Dozens of small satellites share one rocket, but the rocket's flight plan decides where they all go.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$6167df9a-d9e1-572f-8844-d9fc3ec1fde7$ml$::uuid, $ml$2caab2b2-5efa-5beb-97ef-7bd1878265fe$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space, whoever owns the ride decides the orbit and the date.$ml$, $ml$[{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]$ml$::jsonb),
($ml$1c20a05f-4a64-55a2-8255-21504650c567$ml$::uuid, $ml$03cb49a3-a3ae-52ef-824a-a5cbbdda036c$ml$::uuid, 1, $ml$Day 10 · The numbers$ml$, $ml$Planet's 200-plus satellites image all of Earth's land every day. Planet operates more than 200 small satellites that photograph Earth's entire land surface daily, at about 3.7 m per pixel. Maxar's six WorldView Legion satellites capture far sharper 30 cm images and can return to some places up to 15 times a day. How often a fleet comes back over a spot is called revisit.$ml$, $ml$[{"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$ae9e7b3a-3db7-51e8-941e-3e0127ae7edc$ml$::uuid, $ml$03cb49a3-a3ae-52ef-824a-a5cbbdda036c$ml$::uuid, 2, $ml$The metric$ml$, $ml$Revisit is how often a satellite fleet sees the same place. Daily, hourly or 15 times a day: that number decides what change you can watch.$ml$, $ml$[{"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$4c605fe2-9055-53ec-a0b0-ec40e659be61$ml$::uuid, $ml$03cb49a3-a3ae-52ef-824a-a5cbbdda036c$ml$::uuid, 3, $ml$The trade$ml$, $ml$Detail and frequency pull against each other. Planet gets daily global coverage at 3.7 m; Maxar gets 30 cm detail.$ml$, $ml$[{"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$616eecda-3b80-5989-bc79-55fcf298b3c0$ml$::uuid, $ml$03cb49a3-a3ae-52ef-824a-a5cbbdda036c$ml$::uuid, 4, $ml$More low satellites, more passes$ml$, $ml$A low satellite laps Earth every 90 minutes to 2 hours. Add satellites and each spot gets passed more often.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$ce755b0a-6a6a-5143-92ba-d3a8194de964$ml$::uuid, $ml$03cb49a3-a3ae-52ef-824a-a5cbbdda036c$ml$::uuid, 5, $ml$Quote revisit with resolution$ml$, $ml$In imaging, give both numbers: how sharp and how often. Planet is 3.7 m daily; Maxar is 30 cm, up to 15 times a day.$ml$, $ml$[{"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$796e4df7-32ce-5216-bac0-ff3ede18d008$ml$::uuid, $ml$03cb49a3-a3ae-52ef-824a-a5cbbdda036c$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space imaging, how often you see a place matters as much as how sharply.$ml$, $ml$[{"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$4322c552-8682-5465-b56e-62d54addc7ff$ml$::uuid, $ml$7f8cf438-16d5-5964-8d67-f9c46b05be63$ml$::uuid, 1, $ml$Day 10 · The numbers$ml$, $ml$Planet's 200-plus satellites image all of Earth's land every day. Planet operates more than 200 small satellites that photograph Earth's entire land surface daily, at about 3.7 m per pixel. Maxar's six WorldView Legion satellites capture far sharper 30 cm images and can return to some places up to 15 times a day. How often a fleet comes back over a spot is called revisit.$ml$, $ml$[{"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$92ed4c13-5348-5ba9-a4f2-a02068bbd71b$ml$::uuid, $ml$7f8cf438-16d5-5964-8d67-f9c46b05be63$ml$::uuid, 2, $ml$The metric$ml$, $ml$Revisit is how often a satellite fleet sees the same place. Daily, hourly or 15 times a day: that number decides what change you can watch.$ml$, $ml$[{"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$a4fa0477-cb73-54b2-b6ac-92f86c7d5582$ml$::uuid, $ml$7f8cf438-16d5-5964-8d67-f9c46b05be63$ml$::uuid, 3, $ml$The trade$ml$, $ml$Detail and frequency pull against each other. Planet gets daily global coverage at 3.7 m; Maxar gets 30 cm detail.$ml$, $ml$[{"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$d9070588-bdcc-5735-a8cd-ee0f6c25af47$ml$::uuid, $ml$7f8cf438-16d5-5964-8d67-f9c46b05be63$ml$::uuid, 4, $ml$More low satellites, more passes$ml$, $ml$A low satellite laps Earth every 90 minutes to 2 hours. Add satellites and each spot gets passed more often.$ml$, $ml$[{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]$ml$::jsonb),
($ml$040bdf3d-b060-59d4-8f8e-dc3e6aaa5854$ml$::uuid, $ml$7f8cf438-16d5-5964-8d67-f9c46b05be63$ml$::uuid, 5, $ml$Freshness is what sells$ml$, $ml$Customers pay for recent images of places that change. A fleet that returns more often has more to sell.$ml$, $ml$[{"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$79d77b67-f2ba-5c7e-be4d-8a63bc06a42b$ml$::uuid, $ml$7f8cf438-16d5-5964-8d67-f9c46b05be63$ml$::uuid, 6, $ml$The rule$ml$, $ml$In space imaging, how often you see a place matters as much as how sharply.$ml$, $ml$[{"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$75d81bb4-3db4-543e-9a46-a0c5231830b4$ml$::uuid, $ml$e5f27a79-6ca6-565f-9a86-77d0ca60d569$ml$::uuid, 1, $ml$Day 10 · The numbers$ml$, $ml$Planet's 200-plus satellites image all of Earth's land every day. Planet operates more than 200 small satellites that photograph Earth's entire land surface daily, at about 3.7 m per pixel. Maxar's six WorldView Legion satellites capture far sharper 30 cm images and can return to some places up to 15 times a day. How often a fleet comes back over a spot is called revisit.$ml$, $ml$[{"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$7d75e0f0-ae57-5bd1-bad7-5ba9ac56ce45$ml$::uuid, $ml$e5f27a79-6ca6-565f-9a86-77d0ca60d569$ml$::uuid, 2, $ml$The metric$ml$, $ml$Revisit is how often a satellite fleet sees the same place. Daily, hourly or 15 times a day: that number decides what change you can watch.$ml$, $ml$[{"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
($ml$c1bc571a-a9c3-5448-b066-1d98cd24dd7a$ml$::uuid, $ml$e5f27a79-6ca6-565f-9a86-77d0ca60d569$ml$::uuid, 3, $ml$The trade$ml$, $ml$Detail and frequency pull against each other. Planet gets daily global coverage at 3.7 m; Maxar gets 30 cm detail.$ml$, $ml$[{"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]$ml$::jsonb),
