($ml$3fa87236-23ba-52e0-b3e6-d9295ac4c57e$ml$::uuid, $ml$184cf806-d10c-57cd-8139-5b379917f283$ml$::uuid, 1, $ml$Day 13 · Reuse$ml$, $ml$In 2025, 157 of 165 Falcon 9 launches flew on boosters that had flown before. The first stage flies back, lands and is used again. Payload fairing halves are recovered and reflown on many missions. The second stage, which pushes the payload into orbit, is thrown away every time. In 2025 boosters came back on all but three of the 165 flights.$ml$, $ml$[{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]$ml$::jsonb),
($ml$89303198-f0a2-5eaa-9678-f9e09299e588$ml$::uuid, $ml$184cf806-d10c-57cd-8139-5b379917f283$ml$::uuid, 2, $ml$What comes back$ml$, $ml$The booster is the biggest part of the rocket, and it lands. In 2025 boosters returned on all but three missions, two of them expended on purpose.$ml$, $ml$[{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]$ml$::jsonb),
($ml$5f5668b4-358d-5103-bae5-9317fe24dce2$ml$::uuid, $ml$184cf806-d10c-57cd-8139-5b379917f283$ml$::uuid, 3, $ml$What doesn't$ml$, $ml$The second stage is lost on every flight. It is the part that reaches orbit, so it has no easy way home.$ml$, $ml$[{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]$ml$::jsonb),
($ml$44947944-5480-5830-b60b-1fe0e39de455$ml$::uuid, $ml$184cf806-d10c-57cd-8139-5b379917f283$ml$::uuid, 4, $ml$Reuse is now routine$ml$, $ml$Falcon 9 had flown about 620 times by March 2026, with a mission success rate above 99%. All 165 of its 2025 launches delivered their payloads.$ml$, $ml$[{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]$ml$::jsonb),
