($ml$7a1cc19a-e645-5590-9d1a-aab19f563d7d$ml$::uuid, $ml$8d141a41-0ab3-5706-b424-aef32d6a85f7$ml$::uuid, 4, $ml$Some insurers walked away$ml$, $ml$After 2023, some insurers left the space market completely. Fewer insurers means less capacity and higher prices.$ml$, $ml$[{"url": "https://www.satellitetoday.com/sustainability/2024/05/01/slingshot-aerospace-reveals-record-insurance-losses-in-2023-in-new-satellite-deployments-report", "label": "Via Satellite, record space insurance losses in 2023"}]$ml$::jsonb),
