($ml$4b465c4d-8724-5d43-9ee0-62ce6d9ae77a$ml$::uuid, $ml$956de5f5-99ec-5073-ab7e-2135b5312dba$ml$::uuid, 5, $ml$Two satellites, $793 million$ml$, $ml$Just two failed satellites cost insurers about $793 million in 2023.$ml$, $ml$[{"url": "https://www.satellitetoday.com/sustainability/2024/05/01/slingshot-aerospace-reveals-record-insurance-losses-in-2023-in-new-satellite-deployments-report", "label": "Via Satellite, record space insurance losses in 2023"}]$ml$::jsonb),
