($ml$bf0f8225-8321-5cc3-a1d5-cb5843756bc1$ml$::uuid, $ml$693d694c-0cc9-5863-a95a-202c98c078af$ml$::uuid, 3, $ml$The detail$ml$, $ml$Returns are tracked program by program, not just overall. Each category of program has a minimum return a country must receive.$ml$, $ml$[{"url": "https://www.esa.int/About_Us/Business_with_ESA/Business_Opportunities/ESA_an_intergovernmental_customer", "label": "ESA, an intergovernmental customer"}]$ml$::jsonb),
