($ml$d0cfb42f-6c88-5ede-87d0-ee9814e0ed42$ml$::uuid, $ml$01152171-96d1-5e3c-95f5-8bbb33732716$ml$::uuid, 5, $ml$Plan for budget swings$ml$, $ml$Agency budgets are a small slice decided every year. A startup selling to NASA needs customers beyond it.$ml$, $ml$[{"url": "https://www.statista.com/chart/amp/17504/nasas-budget-share-of-the-us-federal-budget", "label": "Statista, NASA's share of the federal budget"}]$ml$::jsonb),
